/**
 * Resolves the view type the editor shows under the current `platform.interfaceMode`. Standard view
 * is a Power-mode-only surface, and the Markers view is shown nowhere.
 *
 * Simple mode's editor offers one view, the Formatted "Preview", and has no menu or shortcut to
 * leave another view. So a view type persisted during a power-mode session must not be shown in
 * simple mode: outside Power, 'standard' and 'markers' resolve to 'formatted' (the editable Simple
 * view). In Power, a saved 'markers' is a value from earlier versions and is shown as Standard
 * view; 'standard' and 'formatted' pass through unchanged. The result is for display only: callers
 * must not write it back to the persisted view type, so returning to power mode restores the user's
 * choice.
 *
 * @param viewType The current (requested or persisted) view type
 * @param isPowerMode Whether `platform.interfaceMode` is 'power'
 * @returns The view type that should actually be shown
 */
export function resolveViewTypeForInterfaceMode(
  viewType: ScriptureEditorViewType,
  isPowerMode: boolean,
): ScriptureEditorViewType {
  if (!isPowerMode) return 'formatted';
  return viewType === 'markers' ? 'standard' : viewType;
}

/**
 * Sentinel that is never a real {@link ScriptureEditorViewType}. It is the `defaultValue` of the web
 * view's `viewType` state, so a value equal to it means no view type has been saved for the web
 * view. `useWebViewState` only reads its default when nothing is persisted and never writes it, so
 * this value never reaches the store.
 */
export const VIEW_TYPE_UNSET = '__view_type_unset_not_a_real_view_type__' as const;

/** The persisted `viewType` state: a saved view type, or {@link VIEW_TYPE_UNSET}. */
export type PersistedViewType = ScriptureEditorViewType | typeof VIEW_TYPE_UNSET;

/**
 * Derives the view the editor shows from the persisted view type. The result is for display only
 * and is never written back.
 *
 * While `platform.interfaceMode` loads, `isPowerMode` is always `false`, so coercing then would
 * hide a Power user's saved Standard view: the persisted value is shown as is, or the formatted
 * view when nothing is saved. Once the mode is known, a never-saved Power tab shows Standard view
 * (the Power default) and everything else goes through {@link resolveViewTypeForInterfaceMode}.
 *
 * @param input.persistedViewType The persisted view type, or {@link VIEW_TYPE_UNSET}
 * @param input.isPowerMode Whether `platform.interfaceMode` is 'power'
 * @param input.isInterfaceModeLoading Whether `platform.interfaceMode` has not resolved yet
 * @returns The view type that should actually be shown
 */
export function getDisplayedViewType({
  persistedViewType,
  isPowerMode,
  isInterfaceModeLoading,
}: {
  persistedViewType: PersistedViewType;
  isPowerMode: boolean;
  isInterfaceModeLoading: boolean;
}): ScriptureEditorViewType {
  if (persistedViewType === VIEW_TYPE_UNSET) {
    return isPowerMode && !isInterfaceModeLoading ? 'standard' : 'formatted';
  }
  if (isInterfaceModeLoading) return persistedViewType;
  return resolveViewTypeForInterfaceMode(persistedViewType, isPowerMode);
}

/** Narrows an untyped saved value to a {@link ScriptureEditorViewType}. */
function isScriptureEditorViewType(viewType: unknown): viewType is ScriptureEditorViewType {
  return viewType === 'formatted' || viewType === 'standard' || viewType === 'markers';
}

/**
 * The Simple-mode marker classes for the Scripture editor's root element (see `_simple-mode.scss`).
 * `character-marker-indicators` turns on the tint and hover line for character markers with no
 * visible style.
 *
 * The character-marker indicator warns against typing inside a marker, so it is on only where the
 * text can be typed into, and stays off until that is known: `isPowerMode` reads `false` while the
 * interface mode loads, and the edit-permission reads default to editable while they load.
 *
 * Pass the durable read-only state, not `isReadOnlyEffective`: that also covers the brief freeze
 * during an automatic Send/Receive, and would flicker the tint on every scheduled sync.
 *
 * @param options.isDurablyReadOnly `undefined` while edit permissions are still resolving
 */
export function getSimpleModeRootClassNames({
  isPowerMode,
  isInterfaceModeLoading,
  isDurablyReadOnly,
}: {
  isPowerMode: boolean;
  isInterfaceModeLoading: boolean;
  isDurablyReadOnly: boolean | undefined;
}): string[] {
  if (isPowerMode) return [];
  if (isInterfaceModeLoading || isDurablyReadOnly !== false) return ['editor-container-simple'];
  return ['editor-container-simple', 'character-marker-indicators'];
}

/**
 * Whether a saved view type makes the editor show Preview, the read-only formatted view. Preview is
 * read-only only in Power; outside Power 'formatted' is the editable Simple view.
 *
 * @param viewType The view type saved in the web view's state (untyped there)
 * @param isPowerMode Whether `platform.interfaceMode` is 'power'
 */
export function showsReadOnlyPreview(viewType: unknown, isPowerMode: boolean): boolean {
  return (
    isPowerMode &&
    isScriptureEditorViewType(viewType) &&
    resolveViewTypeForInterfaceMode(viewType, isPowerMode) === 'formatted'
  );
}

/**
 * The view type each direct view-setting command shows. "Preview" is the user-facing name of the
 * `'formatted'` view type.
 */
export const VIEW_TYPE_FOR_SET_VIEW_COMMAND = {
  'platformScriptureEditor.setViewStandard': 'standard',
  'platformScriptureEditor.setViewPreview': 'formatted',
} as const satisfies Record<string, ScriptureEditorViewType>;

/**
 * Computes the next view type for the view-toggling affordance (the `changeScriptureView` command).
 * Power mode toggles between Standard view and Preview; a saved 'markers' value goes to Standard
 * view. Simple mode has a single view (see {@link resolveViewTypeForInterfaceMode}), so there is
 * nothing to change to, and returning nothing keeps a view type saved in Power from being
 * overwritten.
 *
 * @param viewType The current view type
 * @param isPowerMode Whether `platform.interfaceMode` is 'power'
 * @returns The other view type in Power, or `undefined` in simple mode, where the caller must leave
 *   the saved view type alone
 */
export function getNextViewTypeInCycle(
  viewType: ScriptureEditorViewType,
  isPowerMode: boolean,
): ScriptureEditorViewType | undefined {
  if (!isPowerMode) return undefined;
  return viewType === 'standard' ? 'formatted' : 'standard';
}

/** The two editor messages that can change the saved view type. */
export type ViewChangeMessage =
  | { method: 'changeScriptureView' }
  | { method: 'setScriptureView'; viewType: ScriptureEditorViewType };

/**
 * Decides which view type, if any, a view-changing message should save.
 *
 * `changeScriptureView` toggles per {@link getNextViewTypeInCycle}; in Simple mode there is nothing
 * to toggle to, so nothing is saved. `setScriptureView` saves the requested view type exactly as
 * given and is never coerced by the interface mode: the displayed view type is derived from the
 * saved one by {@link resolveViewTypeForInterfaceMode}, and persisting that coercion (for example
 * while `platform.interfaceMode` is still loading and reads as not Power) would overwrite the
 * user's Power choice.
 *
 * @param message The view-changing message received
 * @param context The current view type and whether `platform.interfaceMode` is 'power'
 * @returns The view type to save, or `undefined` when the saved view type must be left alone
 */
export function getViewTypeToSave(
  message: ViewChangeMessage,
  context: { viewType: ScriptureEditorViewType; isPowerMode: boolean },
): ScriptureEditorViewType | undefined {
  if (message.method === 'setScriptureView') return message.viewType;
  return getNextViewTypeInCycle(context.viewType, context.isPowerMode);
}

/**
 * Check deep equality of two values such that two equal objects or arrays created in two different
 * iframes successfully test as equal
 *
 * WARNING: This checks things that should not be considered for deep equality like object property
 * order. Do not use this if you can use another simpler `deepEqual` implementation like the one in
 * `platform-bible-utils`. If this implementation ever becomes an issue, it may need to be
 * reworked.
 *
 * @param a Object to compare
 * @param b Object to compare
 * @returns `true` if `a` and `b` are deeply equal; `false` otherwise
 */
export function valuesAreDeeplyEqual(a: unknown, b: unknown): boolean {
  // Lightweight deep-equal used across this extension. Uses JSON.stringify which is
  // sufficient for plain data (objects/arrays/primitives) and has the nice property of
  // comparing across iframe boundaries. If you need richer semantics (Dates, Maps, Sets,
  // circular refs) switch to a robust library such as lodash.isequal.
  return JSON.stringify(a) === JSON.stringify(b);
}

// Alias that makes the "across iframes" intent explicit for callers that prefer it.
// Exported with this syntax to preserve the TSDocs
export { valuesAreDeeplyEqual as deepEqualAcrossIframes };

/**
 * Corrects editor USJ version from 3.1 to 3.0. Returns a shallow clone of the object passed in.
 *
 * Currently, this is appropriate to do because the editor seems to work properly with 3.0, but it
 * doesn't handle the version well right now. It always sets it to 3.1 even if it started as 3.0.
 * When we better deal with USFM version differences and when Paratext 9 adds 3.1.2 support, we will
 * need to change how we're handling this.
 */
export function correctEditorUsjVersion(editorUsj: Usj): Usj {
  // Use version 3.0 because `ParatextData.dll` serves 3.0 but the editor isn't handling version
  // well right now
  // eslint-disable-next-line no-type-assertion/no-type-assertion
  return { ...editorUsj, version: '3.0' as typeof USJ_VERSION };
}

/** Whether `jsonPath` names the very last item of `usj`: the last item at every level. */
function isFinalItemOfDocument(usj: Usj, jsonPath: string): boolean {
  const indexes = Array.from(jsonPath.matchAll(/content\[(\d+)\]/g), (match) => Number(match[1]));
  if (indexes.length === 0) return false;
  let { content }: { content?: MarkerContent[] } = usj;
  return indexes.every((index) => {
    if (!content || index !== content.length - 1) return false;
    const item = content[index];
    content = typeof item === 'string' ? undefined : item.content;
    return true;
  });
}

/**
 * A selection location on a text node of `textLength` characters, brought onto that text. The end
 * of the document is spelled on the document's last text as one past the text's end (see
 * `UsjDocumentLocation`), and a caret there sits at the end of that text, so that offset becomes
 * the text's length. Every other location is returned as is — including that offset on any other
 * text, or an offset further past the end, neither of which a location spells and which a caller
 * should treat as the defect it is.
 *
 * @param location The location on text, as the editor reported it.
 * @param textLength The length of the text node the location resolved to.
 * @param usj The document the location addresses.
 * @returns `location`, with the document-end offset brought onto the end of the text.
 */
export function withDocumentEndOnText(
  location: UsjTextContentLocation,
  textLength: number,
  usj: Usj,
): UsjTextContentLocation {
  if (location.offset !== textLength + 1) return location;
  if (!isFinalItemOfDocument(usj, location.jsonPath)) return location;
  return { ...location, offset: textLength };
}

/** The notice shown when a comment cannot be anchored to the selection. */
export type CommentSelectionNoticeKey =
  | '%webView_platformScriptureEditor_error_selectionNotResolved%'
  | '%webView_platformScriptureEditor_error_selectionContainsMarkers%'
  | '%webView_platformScriptureEditor_error_noTextSelected%';

/**
 * The outcome of validating a selection for a new comment: the range to annotate, or the notice to
 * show instead. `warning` is set only when the selection broke the settled-document contract (a
 * defect worth logging), not when the user selected something a comment cannot anchor to.
 */
export type CommentSelectionValidation =
  | { range: { start: UsjDocumentLocation; end: UsjDocumentLocation } }
  | { notice: CommentSelectionNoticeKey; warning?: string };

const NOTICE_NOT_RESOLVED: CommentSelectionNoticeKey =
  '%webView_platformScriptureEditor_error_selectionNotResolved%';
const NOTICE_CONTAINS_MARKERS: CommentSelectionNoticeKey =
  '%webView_platformScriptureEditor_error_selectionContainsMarkers%';
const NOTICE_NO_TEXT: CommentSelectionNoticeKey =
  '%webView_platformScriptureEditor_error_noTextSelected%';

/**
 * Reads the text a validated comment range names. {@link validateCommentSelection} guarantees both
 * ends are text locations on the same path, so the range names one slice of one string.
 *
 * @param range A range from {@link validateCommentSelection}
 * @param usj The document to read from
 * @returns The named text, or `undefined` if the path no longer resolves to a string or the offsets
 *   no longer fit inside it
 */
export function readCommentRangeText(
  range: { start: UsjDocumentLocation; end: UsjDocumentLocation },
  usj: Usj,
): string | undefined {
  if (
    !UsjReaderWriter.isUsjDocumentLocationForTextContent(range.start) ||
    !UsjReaderWriter.isUsjDocumentLocationForTextContent(range.end) ||
    range.start.jsonPath !== range.end.jsonPath
  )
    return undefined;
  try {
    const usjRW = new UsjReaderWriter(usj, { markersMap: USFM_MARKERS_MAP_PARATEXT_3_0 });
    const node = usjRW.jsonPathToUsjNodeAndDocumentLocation(range.start.jsonPath)?.node;
    if (!isString(node)) return undefined;
    const { offset: startOffset } = range.start;
    const { offset: endOffset } = range.end;
    if (startOffset < 0 || endOffset < startOffset || endOffset > node.length) return undefined;
    return node.slice(startOffset, endOffset);
  } catch {
    return undefined;
  }
}

/**
 * Whether a pending comment must be discarded because the text it is anchored to is no longer what
 * was selected. The comment is saved against the frozen range, so a range that now names other text
 * (or none) would store the comment on the wrong characters.
 *
 * @param pending The pending comment's frozen range and the text it named when captured
 * @param usj The current settled document
 */
export function hasPendingCommentTextChanged(
  pending: {
    range: { start: UsjDocumentLocation; end: UsjDocumentLocation };
    anchoredText: string;
  },
  usj: Usj,
): boolean {
  return readCommentRangeText(pending.range, usj) !== pending.anchoredText;
}

/**
 * A range end that names a marker object, with no offset, is the same USFM position as the end of
 * the string right before that marker (Find and Checks spell "up to the footnote" this way). It is
 * rewritten onto that string so it validates the same as the text-end spelling.
 */
function withMarkerEndOnPrecedingText(
  end: UsjDocumentLocation,
  usjRW: UsjReaderWriter,
): UsjDocumentLocation {
  const keys = Object.keys(end);
  if (keys.length !== 1 || !('jsonPath' in end)) return end;
  const match = /^(.*content\[)(\d+)\]$/.exec(end.jsonPath);
  if (!match || Number(match[2]) < 1) return end;
  const previousJsonPath = `${match[1]}${Number(match[2]) - 1}]`;
  try {
    const previous = usjRW.jsonPathToUsjNodeAndDocumentLocation(previousJsonPath);
    if (!isString(previous?.node)) return end;
    const { documentLocation } = previous;
    if (!UsjReaderWriter.isUsjDocumentLocationForTextContent(documentLocation)) return end;
    return { ...documentLocation, offset: previous.node.length };
  } catch {
    return end;
  }
}

/**
 * Validates a selection as the anchor of a new comment against the settled document the selection
 * addresses, and expands a collapsed caret to the word around it.
 *
 * @param selection The editor's (settled) selection
 * @param usj The settled document
 * @returns The range to annotate, or the notice to show (and whether it is a defect to log)
 */
export function validateCommentSelection(
  selection: { start: UsjDocumentLocation; end?: UsjDocumentLocation },
  usj: Usj,
): CommentSelectionValidation {
  const usjRW = new UsjReaderWriter(usj, { markersMap: USFM_MARKERS_MAP_PARATEXT_3_0 });
  const { start } = selection;
  const end = selection.end ? withMarkerEndOnPrecedingText(selection.end, usjRW) : start;

  // A property, closing-marker or attribute location is not text, whatever its path resolves to
  if (
    !UsjReaderWriter.isUsjDocumentLocationForTextContent(start) ||
    !UsjReaderWriter.isUsjDocumentLocationForTextContent(end)
  ) {
    const isCollapsed = !selection.end || serialize(selection.end) === serialize(start);
    return { notice: isCollapsed ? NOTICE_NO_TEXT : NOTICE_CONTAINS_MARKERS };
  }

  let startNode;
  try {
    startNode = usjRW.jsonPathToUsjNodeAndDocumentLocation(start.jsonPath)?.node;
    // Throws if the end does not resolve either
    usjRW.jsonPathToUsjNodeAndDocumentLocation(end.jsonPath);
  } catch (e) {
    return {
      notice: NOTICE_NOT_RESOLVED,
      warning: `Comment insertion: selection jsonPath start=${start.jsonPath} end=${end.jsonPath} does not resolve against the settled USJ! ${getErrorMessage(e)}`,
    };
  }

  // Strings compare by value, so identical sibling strings must be told apart by their paths
  if (!isString(startNode) || start.jsonPath !== end.jsonPath)
    return { notice: NOTICE_CONTAINS_MARKERS };

  // A caret at the end of the document is spelled one past the end of the last text; it sits at
  // the end of that text, which is where the comment anchors.
  const textStart = withDocumentEndOnText(start, startNode.length, usj);
  const textEnd = withDocumentEndOnText(end, startNode.length, usj);

  // An offset past the node means the settled-document contract was broken by a bug or a race;
  // anchoring there would place the comment past the text.
  const offsetPastEnd = [textStart, textEnd].find((location) => location.offset > startNode.length);
  if (offsetPastEnd)
    return {
      notice: NOTICE_NOT_RESOLVED,
      warning: `Comment insertion: selection offset ${offsetPastEnd.offset} at ${textStart.jsonPath} is past the end of the settled node (length ${startNode.length})!`,
    };

  if (textStart.offset !== textEnd.offset) return { range: { start: textStart, end: textEnd } };

  // Collapsed: require a non-whitespace character beside the caret and expand to that word. This
  // is approximate; the backend selects the word by the project's definition of whitespace.
  const { offset } = textStart;
  let charBefore = offset > 0 ? startNode[offset - 1] : '';
  let charAfter = offset < startNode.length ? startNode[offset] : '';
  if (
    (charBefore.length === 0 || isWhiteSpace(charBefore)) &&
    (charAfter.length === 0 || isWhiteSpace(charAfter))
  )
    return { notice: NOTICE_NO_TEXT };

  let endOffset = offset;
  while (charAfter.length > 0 && !isWhiteSpace(charAfter)) {
    charAfter = endOffset + 1 < startNode.length ? startNode[endOffset + 1] : '';
    endOffset += 1;
  }
  let startOffset = offset - 1;
  while (charBefore.length > 0 && !isWhiteSpace(charBefore)) {
    charBefore = startOffset > 0 ? startNode[startOffset - 1] : '';
    startOffset -= 1;
  }
  return {
    range: {
      start: { ...textStart, offset: startOffset + 1 },
      end: { ...textEnd, offset: endOffset },
    },
  };
}

/**
 * Decides whether a view uses the footnotes-pane note model, PT9's: notes are edited in place in
 * the footnotes pane, picking a note moves the text to it, and the picked note's caller is
 * highlighted. Every view the editor shows uses it: Standard view, Power's Preview (the read-only
 * Formatted view, where a note caller still jumps to its note in the pane) and Simple mode's
 * Formatted view, which edits notes exactly as Standard view does while its own text keeps hiding
 * markers. Only a 'markers' view type keeps the popover model, and the editor never displays one
 * once `platform.interfaceMode` has loaded (see {@link resolveViewTypeForInterfaceMode}).
 *
 * The answer does not depend on `isPowerMode`; the option stays so every call site passes the same
 * view facts. While `platform.interfaceMode` is still loading, the displayed view type is the
 * unresolved saved one, so only Standard view counts then.
 *
 * @param options.viewType The scripture editor's current (displayed) view type
 * @param options.isPowerMode Whether `platform.interfaceMode` is 'power'; does not affect the
 *   answer
 * @param options.isInterfaceModeLoading Whether `platform.interfaceMode` is still loading
 * @returns Whether the view uses the footnotes-pane note model
 */
export function usesPaneNoteModel({
  viewType,
  isInterfaceModeLoading,
}: {
  viewType: ScriptureEditorViewType;
  isPowerMode: boolean;
  isInterfaceModeLoading: boolean;
}): boolean {
  if (viewType === 'standard') return true;
  return !isInterfaceModeLoading && viewType === 'formatted';
}

/**
 * Where a note is edited: the footnotes pane (a view using the pane note model — see
 * {@link usesPaneNoteModel}), the popover, or nowhere.
 */
export type NoteEditingSurface = 'pane' | 'popover' | 'none';

/**
 * Decides the note-editing surface for a click on a note caller. A view using the pane note model
 * (see {@link usesPaneNoteModel}) edits notes in the footnotes pane, in place, matching PT9's model;
 * every other view keeps the popover. A read-only text has no editing surface at all — a caller
 * click in a pane-model view still navigates (see {@link decideNoteCallerClickAction}) but never
 * opens an editor; in any other view the caller is inert.
 *
 * @param usesPaneModel Whether the view uses the pane note model ({@link usesPaneNoteModel})
 * @param isReadOnly Whether the text is read-only (editing is disabled)
 * @returns Where a click on a collapsed note caller should open its editor
 */
export function resolveNoteEditingSurface({
  usesPaneModel,
  isReadOnly,
}: {
  usesPaneModel: boolean;
  isReadOnly: boolean;
}): NoteEditingSurface {
  if (isReadOnly) return 'none';
  return usesPaneModel ? 'pane' : 'popover';
}

/**
 * Decides the view options the footnotes pane and its row editor render with. Power mode's pane
 * follows the main editor's view (in Standard view they are Standard's already). Simple mode's pane
 * shows markers as Standard view's does, while the main text keeps Simple's own view options and
 * goes on hiding them. While `platform.interfaceMode` is still loading, `isPowerMode` reads `false`
 * whatever the mode really is, so the pane follows the main editor then: a Power user's pane never
 * briefly takes Simple's answer.
 *
 * @param options.isPowerMode Whether `platform.interfaceMode` is 'power'
 * @param options.isInterfaceModeLoading Whether `platform.interfaceMode` is still loading
 * @param options.mainViewOptions The main editor's view options
 * @param options.standardViewOptions Standard view's view options
 * @returns The view options for the footnotes pane and its row editor
 */
export function resolveFootnotesPaneViewOptions({
  isPowerMode,
  isInterfaceModeLoading,
  mainViewOptions,
  standardViewOptions,
}: {
  isPowerMode: boolean;
  isInterfaceModeLoading: boolean;
  mainViewOptions: ViewOptions | undefined;
  standardViewOptions: ViewOptions;
}): ViewOptions | undefined {
  return isPowerMode || isInterfaceModeLoading ? mainViewOptions : standardViewOptions;
}

/**
 * Decides which note's caller carries the highlight border, mirroring PT9's
 * `CallerHighlightSynchronizer`: the border marks where the focused pane's caret is, so it shows
 * only while the footnotes pane owns DOM focus. Clicking back into the Scripture text leaves the
 * row selected but takes the border off the caller; clicking the row (or its editor) again puts it
 * back. Only a view using the pane note model (see {@link usesPaneNoteModel}) highlights callers at
 * all.
 *
 * PT9's pane has one caret, so the note it is in is the one marked. Here keyboard focus on a row
 * (Tab or the arrow keys) is that caret whenever a row has it, and the selected row otherwise (the
 * row editor, or the pane's chrome, holds focus).
 *
 * @param options.usesPaneModel Whether the view uses the pane note model
 * @param options.paneHasFocus Whether DOM focus is inside the footnotes pane (its row list or its
 *   inline row editor)
 * @param options.focusedRowIndex The footnotes pane row holding DOM focus, or `undefined` when no
 *   row does
 * @param options.selectedIndex The footnotes pane's selected row, or `undefined` when nothing is
 *   selected
 * @returns The note index to highlight, or `undefined` to clear the highlight
 */
export function resolveCallerHighlight({
  usesPaneModel,
  paneHasFocus,
  focusedRowIndex,
  selectedIndex,
}: {
  usesPaneModel: boolean;
  paneHasFocus: boolean;
  focusedRowIndex?: number;
  selectedIndex: number | undefined;
}): number | undefined {
  if (!usesPaneModel || !paneHasFocus) return undefined;
  return focusedRowIndex ?? selectedIndex;
}

/**
 * Decides whether selecting a footnotes pane row ends the open row-editing session. Selecting moves
 * the caller highlight to the newly selected note, so an editor left open on a different note would
 * read as editing the wrong one. The session ends, keeping its edits, whenever the selection lands
 * anywhere but the row being edited.
 *
 * Applies to opening a row as well (a click or Enter on it): the new session starts only after the
 * old one has ended through the normal close path.
 *
 * @param options.paneEditingIndex The row the row editor is open on, or `undefined` when none is
 *   open
 * @param options.selectedIndex The row just selected
 * @returns Whether to end the row-editing session
 */
export function shouldEndPaneNoteEditOnRowSelect({
  paneEditingIndex,
  selectedIndex,
}: {
  paneEditingIndex: number | undefined;
  selectedIndex: number;
}): boolean {
  return paneEditingIndex !== undefined && paneEditingIndex !== selectedIndex;
}

/** Snapshot of the state a collapsed-note caller click decides against. */
export type NoteCallerClickState = {
  /**
   * Whether the clicked note is collapsed (expanded notes are edited in place, not via click).
   * `undefined` (the adaptor could not tell) is treated as not collapsed, matching the original
   * `noteCallerOnClick` guard.
   */
  isCollapsed: boolean | undefined;
  /** The note key of an in-progress note-editing session, if any (popover or pane). */
  editingNoteKey: string | undefined;
  /** Whether the footnote-editor popover is actually shown right now. */
  popoverShown: boolean;
  /** Whether the footnotes pane's visibility TOGGLE is on (it may still lack data to render). */
  paneVisible: boolean;
  /** Whether the footnotes pane is actually rendered (visible toggle AND data loaded). */
  paneRendered: boolean;
  /**
   * Whether the interface is in Power mode. In Power mode a caller click reveals a hidden pane in
   * every view; otherwise only a view using the pane note model reveals it.
   */
  isPowerMode: boolean;
  /** Where the clicked note would be edited; see {@link resolveNoteEditingSurface}. */
  surface: NoteEditingSurface;
  /**
   * Whether the view uses the pane note model (see {@link usesPaneNoteModel}). Only such a view
   * gives a read-only text the navigation half of the pane model; every other view keeps a
   * read-only caller inert.
   */
  usesPaneModel: boolean;
};

/** What a collapsed-note caller click resolves to — see {@link decideNoteCallerClickAction}. */
export type NoteCallerClickAction =
  | 'ignore-expanded'
  | 'ignore-popover-open'
  | 'ignore-read-only'
  | 'open-popover'
  | 'open-pane-editor'
  | 'navigate-only';

/** What a collapsed-note caller click should do — see {@link decideNoteCallerClickAction}. */
export type NoteCallerClickDecision = {
  /**
   * True when `editingNoteKey` belongs to a popover session whose popover is no longer shown —
   * orphaned bookkeeping that would otherwise dead-end every future caller click; clearing it keeps
   * the failure benign. A pane-editor session keeps its key between clicks by design (the row stays
   * open across navigation), so it is never stale. The caller must clear the editing-session refs
   * before acting.
   */
  clearStaleEditingSession: boolean;
  /**
   * What the caller click resolves to:
   *
   * - `ignore-expanded` — the note is expanded (edited in place), so the click does nothing.
   * - `ignore-popover-open` — a footnote-editor popover is already shown, so the click is ignored,
   *   including in a pane-model view the popover outlived a view or interface-mode switch into.
   * - `ignore-read-only` — the text is read-only in a view that does not use the pane note model, so
   *   the caller is inert: the pane's navigation model belongs to pane-model views alone.
   * - `open-popover` — open the footnote-editor popover for the clicked note (every view that does
   *   not use the pane note model).
   * - `open-pane-editor` — open the clicked note's row editor in the footnotes pane (a pane-model
   *   view).
   * - `navigate-only` — the text is read-only in a pane-model view, so there is no editing surface;
   *   the click still navigates (reveals/scrolls the pane) without opening an editor.
   */
  action: NoteCallerClickAction;
  /**
   * Also select/highlight/scroll to the clicked note in the footnotes pane (PT9 navigate-to-note).
   * True when the pane is rendered — or is being shown by this very click ({@link showPane}); the
   * pane's focus-request machinery retries a request that arrives before its data mounts.
   */
  sendPaneFocusRequest: boolean;
  /**
   * Also show the footnotes pane: it is currently toggled off, and either the interface is in Power
   * mode or the view uses the pane note model.
   */
  showPane: boolean;
};

/**
 * Decides what a click on a note caller does. Pure decision logic extracted from
 * `noteCallerOnClick` in the web view so the dead-click branches stay pinned by unit tests.
 *
 * The editing surface ({@link NoteCallerClickState.surface}, from {@link resolveNoteEditingSurface})
 * decides where a routed click opens an editor: the footnotes pane in a view using the pane note
 * model, the popover everywhere else, and nowhere in a read-only text, where the click still
 * navigates without opening an editor. In every case:
 *
 * - An expanded note's caller does nothing (the note is edited in place).
 * - A read-only text outside a pane-model view does nothing either: the pane's navigate-to-note model
 *   belongs to pane-model views, and every other view keeps the caller inert.
 * - While a popover is really shown, a popover-surface click is ignored (one session at a time). A
 *   pane-editor session has no such limit — its row stays open across clicks.
 * - A popover session's key left behind without a shown popover is STALE and must not block the
 *   click; a pane-editor session's key is never stale, since the pane keeps it by design.
 *
 * Alongside whichever action is chosen, the pane highlights the clicked note when it is rendered,
 * and a click also SHOWS the pane when it is toggled off and either the interface is in Power mode
 * or the view uses the pane note model.
 *
 * {@link NoteCallerClickDecision.clearStaleEditingSession} is decided independently of the action
 * and is reported on EVERY branch, the dead-click ones included: orphaned popover bookkeeping has
 * to be cleared whether or not this particular click does anything with it, or it dead-ends every
 * future click.
 */
export function decideNoteCallerClickAction(state: NoteCallerClickState): NoteCallerClickDecision {
  const clearStaleEditingSession =
    state.editingNoteKey !== undefined && !state.popoverShown && state.surface !== 'pane';
  const showPane = !state.paneVisible && (state.isPowerMode || state.usesPaneModel);
  const sendPaneFocusRequest = state.paneRendered || showPane;

  if (!state.isCollapsed)
    return {
      clearStaleEditingSession,
      action: 'ignore-expanded',
      sendPaneFocusRequest: false,
      showPane: false,
    };
  if (state.surface === 'none' && !state.usesPaneModel)
    return {
      clearStaleEditingSession,
      action: 'ignore-read-only',
      sendPaneFocusRequest: false,
      showPane: false,
    };
  // On every editable surface, not just the popover's: a popover opened before the view switched to
  // the pane model applies its text only on Save, so handing the session to the row editor would
  // discard what was typed.
  if (state.surface !== 'none' && state.popoverShown)
    return {
      clearStaleEditingSession,
      action: 'ignore-popover-open',
      sendPaneFocusRequest: false,
      showPane: false,
    };

  let action: NoteCallerClickAction = 'navigate-only';
  if (state.surface === 'pane') action = 'open-pane-editor';
  else if (state.surface === 'popover') action = 'open-popover';
  return { clearStaleEditingSession, action, sendPaneFocusRequest, showPane };
}

/** Snapshot of what an editor change did to an open pane note-editing session. */
export type NoteSessionUpdateState = {
  /** Whether the session's note key still resolves to a note in the editor's document. */
  sessionKeyResolves: boolean;
  /**
   * Whether the change's inserted node key resolves to a note. When the session's key stopped
   * resolving, that inserted note IS the session's note, replaced in place by the row editor's own
   * live-apply (`replaceEmbedUpdate` swaps the node and re-mints its key).
   */
  insertedKeyIsNote: boolean;
  /**
   * Whether the session note's current content differs from the comparison baseline — what the row
   * editor is known to be showing. Only meaningful while {@link sessionKeyResolves}.
   */
  noteChanged: boolean;
};

/** What an editor change does to an open pane note-editing session. */
export type NoteSessionUpdateAction = 'rekey' | 'end-session' | 'follow-note';

/** What an editor change should do to an open pane session — see {@link decideNoteSessionUpdate}. */
export type NoteSessionUpdateDecision = {
  /**
   * What the change resolves to:
   *
   * - `rekey` — the session's note was replaced in place, so the session follows the new key.
   * - `end-session` — the note is gone and nothing replaced it, so there is nothing left to edit.
   * - `follow-note` — the note is still there; the editing row follows its (possibly moved) index.
   */
  action: NoteSessionUpdateAction;
  /**
   * Hand the row editor a fresh `noteOps` ARRAY IDENTITY, which is what reloads its document. Only
   * ever true for a change that came from somewhere other than the row editor itself: reloading a
   * row editor mid-typing throws away its caret and replaces its document with content that is
   * missing anything still inside its apply debounce.
   */
  reloadRowEditor: boolean;
  /**
   * Refresh the comparison baseline ({@link NoteSessionUpdateState.noteChanged}) to the note's
   * current content. True on a re-key — where the row editor's own live-apply is the new content —
   * as well as on a reload, so the next external change is compared against what the row editor is
   * actually showing rather than against the ops it was first loaded with.
   */
  refreshBaseline: boolean;
};

/**
 * Decides what an editor change does to an open footnotes-pane note-editing session. Pure decision
 * logic extracted from `handleEditorialUsjChange` in the web view, where the reload/baseline
 * invariant below has no component-level test harness of its own.
 *
 * The ops cannot tell the row editor's own live-apply from a note inserted in the text: both carry
 * a note insert-embed op. The DOCUMENT tells them apart — the row editor's apply replaces the
 * session's note node, so the session's key stops resolving while an inserted key resolves to the
 * replacement.
 *
 * The invariant that makes the row editor usable: a reload is for changes from ELSEWHERE only, and
 * the baseline the "changed?" comparison runs against must track the row editor's own applies too.
 * A baseline left at the ops the row was loaded with makes every later external change compare
 * unequal, reloading the row editor once per edit cycle.
 */
export function decideNoteSessionUpdate(state: NoteSessionUpdateState): NoteSessionUpdateDecision {
  if (!state.sessionKeyResolves) {
    if (state.insertedKeyIsNote)
      return { action: 'rekey', reloadRowEditor: false, refreshBaseline: true };
    return { action: 'end-session', reloadRowEditor: false, refreshBaseline: false };
  }
  return {
    action: 'follow-note',
    reloadRowEditor: state.noteChanged,
    refreshBaseline: state.noteChanged,
  };
}

/**
 * The notes in a document the editor produced, in document order - the list the footnotes pane
 * shows and `EditorRef.getNoteIndex` indexes.
 *
 * The editor stamps its documents with a USJ version the markers map is not declared for, and
 * `UsjReaderWriter` warns on every read when that happens; this corrects the version first (see
 * {@link correctEditorUsjVersion}) so reading the notes on every keystroke logs nothing.
 *
 * @param editorUsj A document from the editor (`EditorRef.getUsj`) or the PDP
 * @returns The notes, as `UsjReaderWriter.findAllNotes` returns them
 */
export function findEditorUsjNotes(editorUsj: Usj): MarkerObject[] {
  return new UsjReaderWriter(correctEditorUsjVersion(editorUsj), {
    markersMap: USFM_MARKERS_MAP_PARATEXT_3_0,
  }).findAllNotes();
}

/**
 * Whether the editor's freshly settled document has to be republished to the footnotes pane.
 *
 * Typing in the Scripture body changes the document on every keystroke and the note list on none of
 * them, and republishing regardless re-renders the whole web view - the Scripture editor included -
 * per character, which is felt as typing lag with the pane open. Editing inside a row editor does
 * change a note, but only once per live-apply debounce, so the pane still repaints as fast as
 * anything it shows actually changes.
 *
 * That makes the published document's guarantee "a document whose NOTES are current" rather than
 * "the current document" - which is what the pane and `EditorRef.getNoteIndex` have to agree on.
 *
 * @param newNotes The notes read out of the document about to be published, or `undefined` when
 *   they could not be read - a document this reader cannot walk must publish, so it can never wedge
 *   the pane on stale notes
 * @param publishedNotes The notes the pane is already showing, or `undefined` when nothing has been
 *   published yet
 * @returns Whether to publish the document
 */
export function shouldPublishPaneDocument(
  newNotes: MarkerObject[] | undefined,
  publishedNotes: MarkerObject[] | undefined,
): boolean {
  if (!newNotes || !publishedNotes) return true;
  return !valuesAreDeeplyEqual(newNotes, publishedNotes);
}

/**
 * The Scripture reference of the verse a note sits in, so selecting a note in the footnotes pane
 * (or clicking its caller) can move the scroll group there, as PT9's notes pane does.
 *
 * Resolved from the USJ rather than from the editor's own selection reporting, so a read-only text
 * — which has no caret to report from — navigates exactly like an editable one.
 *
 * Only the VERSE is taken from the note's position: the editor holds exactly one chapter, so book,
 * chapter and versification all ride through from the reference in effect. That also keeps a
 * document with no `\c` of its own (which resolves as chapter 0) from navigating the user into
 * front matter.
 *
 * @param usj The chapter document the pane and `EditorRef.getNoteIndex` both index; pass the
 *   editor's live document, not the PDP's, or an index typed ahead of the save debounce names a
 *   different note
 * @param noteIndex Document-order index of the note among the chapter's notes
 * @param currentScrRef The reference in effect now — everything but the verse comes from it
 * @returns The reference to publish, or `undefined` when the note cannot be located (no note at
 *   that index, or USJ this reader cannot walk) — in which case the caller should leave the current
 *   reference alone rather than guess, and report that it did
 */
export function resolveNoteVerseRef(
  usj: Usj | undefined,
  noteIndex: number,
  currentScrRef: SerializedVerseRef,
): SerializedVerseRef | undefined {
  if (!usj || noteIndex < 0) return undefined;
  try {
    // Corrected for the same reason as in `findEditorUsjNotes`.
    const usjReaderWriter = new UsjReaderWriter(correctEditorUsjVersion(usj), {
      markersMap: USFM_MARKERS_MAP_PARATEXT_3_0,
    });
    const note = usjReaderWriter.findAllNotes()[noteIndex];
    if (!note) return undefined;
    const { verseRef } = usjReaderWriter.nodeToUsfmVerseRefVerseLocation(
      note,
      undefined,
      currentScrRef.book,
    );
    // `verse` is the text form of the verse being LEFT, set when it is a range or segment (`3-4`,
    // `2a`); kept, it would contradict the note's own `verseNum` for every reader that prefers it.
    const noteRef: SerializedVerseRef = { ...currentScrRef, verseNum: verseRef.verseNum };
    delete noteRef.verse;
    return noteRef;
  } catch {
    // Malformed USJ is a navigation that does not happen, never a thrown error out of a click
    // handler. Stays silent here — this is a pure helper with no logger of its own — and the
    // caller reports the `undefined` it gets back.
    return undefined;
  }
}

// #region Editor Title Formatting

const PROJECT_ID_TITLE_FORMAT_STRING_KEY = '%webView_platformScriptureEditor_title_format%';
const EDITABLE_KEY = '%webView_platformScriptureEditor_title_editable_indicator%';
const READONLY_KEY = '%webView_platformScriptureEditor_title_readonly_indicator%';
const RESOURCE_VIEWER_KEY = '%webView_platformScriptureEditor_title_readonly_no_project%';
const SCRIPTURE_EDITOR_KEY = '%webView_platformScriptureEditor_title_editable_no_project%';

export async function formatEditorTitle(
  unformattedTitle: string | undefined,
  projectId: string | undefined,
  isReadOnly: boolean,
  getProjectName: (projectId: string) => Promise<string>,
  getLocalizedStrings: (selectors: LocalizationSelectors) => Promise<LanguageStrings>,
): Promise<string> {
  let title = unformattedTitle;
  if (!title) {
    if (projectId) title = PROJECT_ID_TITLE_FORMAT_STRING_KEY;
    else title = isReadOnly ? RESOURCE_VIEWER_KEY : SCRIPTURE_EDITOR_KEY;
  }
  if (isLocalizeKey(title)) {
    const localizedStrings = await getLocalizedStrings({
      localizeKeys: [EDITABLE_KEY, READONLY_KEY, title],
    });
    const localizedTitleFormatStr = localizedStrings[title];
    const localizedEditable = localizedStrings[EDITABLE_KEY];
    const localizedReadonly = localizedStrings[READONLY_KEY];

    let projectName = projectId;
    if (projectId) projectName = await getProjectName(projectId);

    title = formatReplacementString(localizedTitleFormatStr, {
      projectId: projectName,
      editable: isReadOnly ? localizedReadonly : localizedEditable,
    });
  }

  return title;
}

/**
 * The project name a tab title shows: the project's short name (`platform.name`), falling back to
 * the project id when the setting is unavailable.
 *
 * Deliberately NOT `formatProjectName`. A tab strip is the most space-constrained surface in the
 * app, so appending the full name would push the short name — the field a Paratext user identifies
 * a project by — toward the truncation it is supposed to survive. Short-name-first holds here in
 * the strongest form available: the short name is the only name shown.
 *
 * Lives here rather than inline in `main.ts`'s title callback so that the choice of setting is
 * pinned by a test. `formatEditorTitle`'s own tests inject this name, so they stay green whichever
 * setting feeds them; without this seam, a swap to `platform.fullName` changes every tab title and
 * no test notices.
 *
 * The project-id fallback is defensive rather than reachable in production: the C# data provider
 * special-cases `platform.name` to `scrText.Name`, and the setting carries a contribution default,
 * so a project served by it always answers. It guards a third-party project data provider that does
 * not, and an unavailable provider.
 *
 * @param papi The PAPI backend.
 * @param projectId The project whose name the tab shows.
 * @returns The project's short name, or the project id when it has none.
 */
export async function getTabTitleProjectName(
  papi: typeof PapiBackend,
  projectId: string,
): Promise<string> {
  const pdp = await papi.projectDataProviders.get('platform.base', projectId);
  return (await pdp.getSetting('platform.name')) ?? projectId;
}

// #endregion Editor Title Formatting

/**
 * Opens the comment list for an editor and selects a specific thread.
 *
 * @param editorWebViewId The ID of the editor web view (used to determine which project's comments)
 * @param threadId The ID of the thread to select
 */
export async function openCommentListAndSelectThread(
  papi: typeof PapiBackend | typeof PapiFrontend,
  editorWebViewId: string,
  threadId: string,
): Promise<void> {
  const commentListWebViewId = await papi.commands.sendCommand(
    'legacyCommentManager.openCommentList',
    editorWebViewId,
    { threadIdToSelect: threadId },
  );

  if (!commentListWebViewId) {
    throw new Error(`No WebView ID returned`);
  }
}

/**
 * Opens the comment list for an editor and selects a specific thread.
 *
 * @param editorWebViewId The ID of the editor web view (used to determine which project's comments)
 * @param threadId The ID of the thread to select
 */
export async function openCommentListAndSelectThreadSafe(
  papi: typeof PapiBackend | typeof PapiFrontend,
  editorWebViewId: string,
  threadId: string,
): Promise<void> {
  try {
    await openCommentListAndSelectThread(papi, editorWebViewId, threadId);
  } catch (e) {
    papi.logger.warn(
      `Failed to open comment list from WebView ${editorWebViewId} and select thread ${threadId}: ${getErrorMessage(e)}`,
    );
  }
}

/**
 * Selects/scrolls to a specific thread in the fixed Column 3 Comment List panel, without opening a
 * second, editor-anchored Comments panel. Logs and swallows any failure (e.g. the panel isn't in
 * the current layout) rather than throwing, since this is used for best-effort navigation feedback
 * after an action has already succeeded (e.g. a comment was already created).
 *
 * @param threadId The ID of the thread to select and scroll to in the panel
 * @param bringToFront Whether to also bring the panel's tab to the front. Pass `false` for
 *   background confirmation (e.g. after inserting a comment, so the user's current Column 3 tab
 *   isn't interrupted) or `true` for an explicit "show me this comment" navigation.
 * @param editorWebViewId The editor the thread belongs to. If given, the panel is first pointed at
 *   that editor's project when it shows another one.
 */
export async function selectCommentThreadInPanelSafe(
  papi: typeof PapiBackend | typeof PapiFrontend,
  threadId: string,
  bringToFront: boolean,
  editorWebViewId?: string,
): Promise<void> {
  try {
    const panelWebViewId = await papi.commands.sendCommand(
      'legacyCommentManager.selectCommentThreadInPanel',
      threadId,
      bringToFront,
      editorWebViewId,
    );
    if (!panelWebViewId) throw new Error('No WebView ID returned');
  } catch (e) {
    papi.logger.warn(
      `Failed to select thread ${threadId} in the Comment List panel: ${getErrorMessage(e)}`,
    );
  }
}

/**
 * Brings a comment thread into view where the current interface mode keeps comments. Power mode
 * opens (or focuses) the editor-anchored comment list on the thread. Simple mode has no such list —
 * its comments live in the fixed Column 3 Comments tab — so that tab is brought to the front with
 * the thread selected instead, after pointing that tab at the editor's project if it shows another
 * one; opening the editor-anchored list there would add a second Comments column. Logs and swallows
 * any failure, like the two functions it chooses between.
 *
 * @param papi The PAPI to send the navigation command through
 * @param options.isPowerMode Whether the app is in Power interface mode
 * @param options.editorWebViewId The ID of the editor web view the thread belongs to, which decides
 *   the project whose comments are shown
 * @param options.threadId The ID of the thread to show
 */
export async function showCommentThreadForInterfaceMode(
  papi: typeof PapiBackend | typeof PapiFrontend,
  {
    isPowerMode,
    editorWebViewId,
    threadId,
  }: { isPowerMode: boolean; editorWebViewId: string; threadId: string },
): Promise<void> {
  if (isPowerMode) {
    await openCommentListAndSelectThreadSafe(papi, editorWebViewId, threadId);
    return;
  }

  await selectCommentThreadInPanelSafe(papi, threadId, true, editorWebViewId);
}

// #region USJ location conversion helper functions

/**
 * Figure out the location properties on a {@link ScriptureRange} `start` or `end`. Takes the complex
 * disparate USFM and USJ location types and returns the properties in them
 *
 * @param rangeLocation {@link ScriptureRange} `start` or `end`
 * @param baseVerseRef Verse reference to start with. In some cases, only certain properties on this
 *   verse reference will be changed
 * @returns Location properties found in `rangeLocation`
 */
function determineLocationProperties(
  rangeLocation: ScriptureRange['start'],
  baseVerseRef: SerializedVerseRef,
): {
  /** `undefined` if not found */
  documentLocation: UsjDocumentLocation | undefined;
  verseRef: SerializedVerseRef;
  /** `undefined` if not found */
  verseOffset: number | undefined;
} {
  let documentLocation: UsjDocumentLocation | undefined;
  let verseRef = { ...baseVerseRef };
  let verseOffset: number | undefined;

  if ('jsonPath' in rangeLocation || 'documentLocation' in rangeLocation) {
    const chapterLocation =
      UsjReaderWriter.usjChapterLocationToUsjVerseRefChapterLocation(rangeLocation);
    verseRef.book = chapterLocation.verseRef.book;
    verseRef.chapterNum = chapterLocation.verseRef.chapterNum;
    documentLocation = chapterLocation.documentLocation;
  } else {
    const startVerseLocation =
      UsjReaderWriter.usfmVerseLocationToUsfmVerseRefVerseLocation(rangeLocation);
    verseRef = startVerseLocation.verseRef;
    verseOffset = startVerseLocation.offset;
  }

  return {
    documentLocation,
    verseRef,
    verseOffset,
  };
}

/** Result of converting a ScriptureRange to an editor-usable range */
interface ConvertedEditorRange {
  /** The scripture reference for the start of the range */
  verseRef: SerializedVerseRef;
  /** The editor-usable range with start and end locations in USJ format */
  editorRange: {
    start: UsjDocumentLocation;
    end: UsjDocumentLocation;
  };
  /** The UsjReaderWriter instance used for conversion, for further text extraction */
  usjReaderWriter: UsjReaderWriter;
}

/**
 * Convert a ScriptureRange to an editor-usable range format. This function handles the complex
 * conversion between USFM/USJ location types and the editor's internal range format.
 *
 * @param range The ScriptureRange to convert
 * @param projectId The project ID to fetch USJ data from
 * @returns The converted range with editor-usable format and a UsjReaderWriter for text extraction
 * @throws If the range spans chapters or books, or if required data cannot be fetched
 */
export async function convertScriptureRangeToEditorRange(
  papi: typeof PapiBackend,
  range: ScriptureRange,
  projectId: string,
): Promise<ConvertedEditorRange> {
  // Figure out the information needed to make the USJ range to give to the editor:
  // book, chapter, and start/end document locations.
  // Also need to get the verse to set the scroll group verse to because the editor doesn't
  // do it automatically right now
  let startVerseRef: SerializedVerseRef = { book: '', chapterNum: 0, verseNum: -1 };
  let startDocumentLocation: UsjDocumentLocation | undefined;
  let endDocumentLocation: UsjDocumentLocation | undefined;

  // May need to use verse refs and offsets from the USFM verse location to get USJ offsets
  let endVerseRef: SerializedVerseRef = { book: '', chapterNum: 0, verseNum: 0 };

  // Figure out the book and chapter and the jsonPaths and offsets if they're in the range
  // passed to us
  // Process the starting location
  const { verseOffset: startVerseOffset, ...startLocationProperties } = determineLocationProperties(
    range.start,
    startVerseRef,
  );
  ({ documentLocation: startDocumentLocation, verseRef: startVerseRef } = startLocationProperties);

  // Process the ending location
  const { verseOffset: endVerseOffset, ...endLocationProperties } = determineLocationProperties(
    range.end,
    endVerseRef,
  );
  ({ documentLocation: endDocumentLocation, verseRef: endVerseRef } = endLocationProperties);
  if (
    startVerseRef.book !== endVerseRef.book ||
    startVerseRef.chapterNum !== endVerseRef.chapterNum
  )
    throw new Error(
      'Could not get targetScrRef from range! Selection range cannot (yet) span chapters or books',
    );

  // Get the USJ chapter we're on so we can determine the missing USJ range properties
  const pdp = await papi.projectDataProviders.get('platformScripture.USJ_Chapter', projectId);
  const usjChapter = await pdp.getChapterUSJ(startVerseRef);

  if (!usjChapter)
    throw new Error(
      `USJ Chapter for project id ${projectId} target scrRef ${serialize(startVerseRef)} is undefined!`,
    );

  const usjRW = new UsjReaderWriter(usjChapter, { markersMap: USFM_MARKERS_MAP_PARATEXT_3_0 });

  startDocumentLocation ??= usjRW.usfmVerseLocationToUsjDocumentLocation(
    startVerseOffset === undefined
      ? startVerseRef
      : { verseRef: startVerseRef, offset: startVerseOffset },
  );

  endDocumentLocation ??= usjRW.usfmVerseLocationToUsjDocumentLocation(
    endVerseOffset === undefined ? endVerseRef : { verseRef: endVerseRef, offset: endVerseOffset },
  );

  // If we don't have which verse we're setting the scroll group to, get it. A USJ document
  // location range only carries a chapter's own USJ, which has a book `id` marker for chapter 1
  // and lacks one otherwise (see UsjChapterLocation), so fall back to the book already resolved
  // above for this range.
  if (startVerseRef.verseNum === -1) {
    const startUsfmLocation = usjRW.usjDocumentLocationToUsfmVerseRefVerseLocation(
      startDocumentLocation,
      startVerseRef.book,
    );
    startVerseRef.verseNum = startUsfmLocation.verseRef.verseNum;
  }

  if (!startDocumentLocation || !endDocumentLocation)
    throw new Error('Could not determine USJ document locations for selection range');

  return {
    verseRef: startVerseRef,
    editorRange: {
      start: startDocumentLocation,
      end: endDocumentLocation,
    },
    usjReaderWriter: usjRW,
  };
}

// #endregion USJ location conversion helper functions

/**
 * All Scroll Group IDs that are intended to be shown in scroll group selectors. This is a
 * placeholder and will be refactored significantly in
 * https://github.com/paranext/paranext-core/issues/788
 */
export const availableScrollGroupIds = [undefined, ...new Array(5).keys()];

/**
 * `MarkerType.Paragraph` markers that are never valid to select via a plain paragraph-style retag,
 * because they are instead applied through dedicated, structure-aware mechanisms.
 */
export const PROGRAMMATICALLY_APPLIED_PARAGRAPH_MARKERS: ReadonlySet<string> = new Set(['id', 'c']);

/**
 * Every USFM paragraph-style marker known to {@link usfmMarkers} that a user can validly choose to
 * apply via a plain paragraph-style retag. (Excludes
 * {@link PROGRAMMATICALLY_APPLIED_PARAGRAPH_MARKERS}.)
 */
export const selectableParagraphMarkers: readonly string[] = Object.keys(usfmMarkers)
  .filter(
    (marker) =>
      isParagraphMarker(marker) && !PROGRAMMATICALLY_APPLIED_PARAGRAPH_MARKERS.has(marker),
  )
  .sort();

/**
 * True when a marker has a real (potentially localized) title available via
 * {@link getParagraphMarkerTitle} (as displayed in tooltips, the Paragraph combo box
 * trigger/switcher, etc.) Some titles may not be displayed in all possible contexts.
 */
export function hasDisplayableParagraphMarkerTitle(marker: string): boolean {
  return isParagraphMarker(marker);
}

/**
 * Builds the localize key for a paragraph marker's description.
 *
 * @param marker Marker code, without its leading backslash (e.g. `p`, not `\p`)
 */
export function paragraphMarkerNameKey(marker: string): LocalizeKey {
  return `%paragraphMenu_${marker}_markerDescription%`;
}

/**
 * Resolves the localized title for a paragraph marker. Returns `undefined` when no title is
 * available at all ({@link hasDisplayableParagraphMarkerTitle} is `false`) — when the marker isn't a
 * paragraph marker in `usfmMarkers` at all. Otherwise, returns whatever `localizedStrings`
 * currently has for the marker's key (from the `useLocalizedStrings` hook).
 *
 * @param marker Marker code to look up, without its leading backslash (e.g. `p`, not `\p`)
 * @param localizedStrings The localized strings to resolve the title from
 */
export function getParagraphMarkerTitle(
  marker: string,
  localizedStrings: LanguageStrings,
): string | undefined {
  if (!hasDisplayableParagraphMarkerTitle(marker)) return undefined;
  return localizedStrings[paragraphMarkerNameKey(marker)];
}

/**
 * Generates the marker menu list items specifically inserting appropriate action functions using
 * the provided `editorRef` parameter and localizes the marker titles with the provided
 * `localizedStrings` parameter
 *
 * @param editorRef Provided ref for the editor component
 * @param localizedStrings The localized strings to use to localize the marker titles
 * @param isStructureProtected Whether the project's paragraph structure is currently protected;
 *   when `true`, the action will call `notifyStructureProtected` instead of formatting the
 *   paragraph
 * @param notifyStructureProtected Callback to invoke when the user attempts a paragraph format
 *   while structure is protected
 * @param restoreSelection Callback invoked immediately before `formatPara` to put the caret back
 *   where the user last had it. Opening the dropdown's popover moves focus off the editor input,
 *   and Lexical's blur processing can null the live selection outright — `formatPara` then has no
 *   paragraph to retag and the pick silently does nothing. The caller supplies this rather than
 *   this module doing the restore itself: the restore needs `restoreSelectionIfLost` and the
 *   focus-out selection capture, both of which live in web-view-only code this
 *   extension-host-reachable module may not import (see the note at the bottom of this file).
 *   Omitting it leaves the retag exposed to the lost-caret failure, so callers that can lose focus
 *   to the menu should always pass it. It must leave a selected paragraph marker alone:
 *   `formatPara` retags that paragraph directly, and a caret restored over it would send the retag
 *   to the caret's paragraph instead.
 * @param isChapterLoading Reports whether another chapter is loading, during which the editor still
 *   shows the chapter being left and an edit would be dropped. A pick does nothing while it returns
 *   `true`. Omitting it never blocks.
 * @returns List of marker menu items to be used for the paragraph menu
 */
export function generateParagraphMenuListItems(
  editorRef: MutableRefObject<EditorRef | null>,
  localizedStrings: LanguageStrings,
  isStructureProtected: boolean,
  notifyStructureProtected: () => void,
  restoreSelection?: () => void,
  isChapterLoading?: () => boolean,
): MarkerMenuItem[] {
  return selectableParagraphMarkers.map((marker) => {
    // The trailing detail column would otherwise sit empty for exactly the menu this feature is
    // named after. `usfmMarkers[marker].description` is a localize key the web view already
    // resolves (it loads every marker description), so this needs no new key and no new
    // localization work. Falls back to no subtitle for any marker without a description.
    const descriptionKey = usfmMarkers[marker]?.description;
    const markerMenuItem: MarkerMenuItem = {
      marker,
      title: getParagraphMarkerTitle(marker, localizedStrings) ?? marker,
      subtitle: descriptionKey ? localizedStrings[descriptionKey] : undefined,
      action: () => {
        if (isChapterLoading?.()) return;
        // Defense-in-depth: unreachable while the paragraph control is disabled
        // (`disabled={isStructureProtected}` in the web view), so the popover never opens and this
        // action never runs. Kept as a second layer of protection in case that disabled state is
        // ever loosened or the menu wiring changes.
        if (isStructureProtected) {
          notifyStructureProtected();
          return;
        }
        // Re-picking a selected marker's own marker (a second Enter on the menu the editor opened,
        // which highlights that row) must change nothing. `formatPara` would still rewrite the
        // marker and leave an undo step that does nothing, so skip it. Only for a selected marker:
        // with a range selection, the same pick retags the other paragraphs the range covers.
        if (editorRef.current?.getSelectedParaMarker() === marker) return;
        // Restore the caret BEFORE applying, exactly as the `\` and Enter marker palettes do
        // before their applies: this menu opens in a popover that takes focus off the editor
        // input, so by the time an item is picked the live selection may already be gone, and
        // `formatPara` refuses when there is neither a selection nor a selected paragraph marker.
        restoreSelection?.();
        editorRef.current?.formatPara(marker);
      },
    };
    return markerMenuItem;
  });
}

// NOTE: the stylesheet-driven inline marker menu generator and the command-palette helpers live in
// `platform-scripture-editor.web-view.utils.ts`, NOT here — they import runtime values from
// `@eten-tech-foundation/platform-editor`, whose React-bundling dist must never reach the
// extension-host (`main.ts`) bundle this module is part of. This module is restricted to
// `import type` from that package. See that file's header for the full activation-failure story.

// #region Open Editor Dispatch

/**
 * Tagged-union result describing where a new Scripture Editor open should be routed.
 *
 * - `focus-existing` — a Scripture Editor for the requested project is already open; the caller
 *   should focus that tab (via `openWebView` with `existingId`) rather than creating a new one.
 * - `replace-tab` — the caller should call `openWebView` with `{ type: 'replace-tab', targetTabId }`
 *   so the named tab is swapped out for a fresh editor.
 * - `open-new` — no targeting hint applies; the caller should call `openWebView` without a layout so
 *   the platform places the new tab using its default rules.
 */
export type OpenEditorDispatch =
  | { kind: 'focus-existing'; existingId: string }
  | { kind: 'replace-tab'; targetTabId: string }
  | { kind: 'open-new' };

/** Scripture Editor tab info consumed by {@link resolveOpenEditorDispatch}. */
export type ScriptureEditorInfo = { id: string; projectId?: string; isReadOnly: boolean };

/**
 * Convert open web view definitions to the Scripture Editor info shape consumed by
 * {@link resolveOpenEditorDispatch}: filters to Scripture Editor web views and extracts `id`,
 * `projectId`, and `isReadOnly` from each definition.
 *
 * Pure function — does not touch PAPI. The caller is responsible for fetching the definitions
 * (`papi.webViews.getAllOpenWebViewDefinitions`).
 */
export function toScriptureEditorInfos(
  allOpenDefs: readonly SavedWebViewDefinition[],
): ScriptureEditorInfo[] {
  return allOpenDefs
    .filter((def) => def.webViewType === SCRIPTURE_EDITOR_WEBVIEW_TYPE)
    .map((def) => ({
      id: def.id,
      projectId: def.projectId,
      // WebView state isn't statically typed, but `getWebViewDefinition` always stores
      // `isReadOnly` as boolean here. Treat any other value as `false` for safety.
      // eslint-disable-next-line no-type-assertion/no-type-assertion
      isReadOnly: !!(def.state?.isReadOnly as boolean | undefined),
    }));
}

/**
 * Decide where to route a Scripture Editor open request based on what's currently in the dock and
 * which interface mode the platform is in.
 *
 * Pure function — does not touch PAPI. The caller is responsible for fetching the inputs
 * (`papi.webViews.getAllOpenWebViewDefinitions` filtered to Scripture Editors, the requested
 * `projectId`, `papi.settings.get('platform.interfaceMode')`, and the optional caller override).
 *
 * Behavior splits cleanly on `interfaceMode`:
 *
 * **Simple mode** — the platform's editor column hosts exactly one Scripture Editor at a time.
 * Every open routes there, and the caller-supplied `existingTabIdToReplace` is intentionally
 * ignored (e.g., the column 3 NewTab passes its own id so it can be replaced in place; in simple
 * mode we route to the editor column instead). Editable Scripture Editors and read-only Resource
 * Viewers share the same `webViewType` but are different views — they're keyed on `(projectId,
 * isReadOnly)` here so opening a Resource Viewer for project X while an editable editor for project
 * X is already open replaces (not focuses) it.
 *
 * 1. Same `(projectId, isReadOnly)` already open → `focus-existing` on that tab.
 * 2. Some other Scripture Editor is open (different project, or same project but different readonly
 *    mode) → `replace-tab` on the first existing Scripture Editor.
 * 3. No Scripture Editor exists at all → `open-new` (graceful degradation; the simple layout normally
 *    always has the editor slot).
 *
 * **Power mode** — unchanged from the platform's original P9-style behavior:
 *
 * 1. Caller-supplied `existingTabIdToReplace` → `replace-tab` on that tab.
 * 2. An empty Scripture Editor (no `projectId`) exists → `replace-tab` on the placeholder.
 * 3. Otherwise → `open-new`. (Opening the same project twice in power mode produces two tabs.)
 *
 * @param allScriptureEditors All currently-open Scripture Editor web view definitions (filtered by
 *   the caller from `getAllOpenWebViewDefinitions`). Only `id`, `projectId`, and `isReadOnly` are
 *   read. `isReadOnly` should be derived from each definition's `state?.isReadOnly`.
 * @param projectId The project the caller wants to open. The caller should not invoke this helper
 *   until project selection has resolved.
 * @param isReadOnly Whether the caller is opening a read-only Resource Viewer (`true`) or an
 *   editable Scripture Editor (`false`). Used only in simple mode; ignored in power mode.
 * @param interfaceMode The current `platform.interfaceMode` setting value.
 * @param existingTabIdToReplace Caller-supplied tab to replace; honored in power mode but ignored
 *   in simple mode (where every open goes to the editor column).
 * @returns The dispatch decision — see {@link OpenEditorDispatch}.
 */
export function resolveOpenEditorDispatch(
  allScriptureEditors: ReadonlyArray<{ id: string; projectId?: string; isReadOnly?: boolean }>,
  projectId: string,
  isReadOnly: boolean,
  interfaceMode: 'simple' | 'power',
  existingTabIdToReplace: string | undefined,
): OpenEditorDispatch {
  if (interfaceMode === 'simple') {
    // Simple mode invariant: every Scripture Editor open lands in the editor column. The
    // caller-supplied `existingTabIdToReplace` is intentionally ignored — e.g., column 3's
    // NewTab passes its own id so it can be replaced in place, but in simple mode we route to
    // the editor column instead so we never have two editors for the same (or different) project.
    const existingForSameView = allScriptureEditors.find(
      (def) => def.projectId === projectId && !!def.isReadOnly === isReadOnly,
    );
    if (existingForSameView) {
      return { kind: 'focus-existing', existingId: existingForSameView.id };
    }
    if (allScriptureEditors.length > 0) {
      return { kind: 'replace-tab', targetTabId: allScriptureEditors[0].id };
    }
    // Graceful degradation: simple layout should always have a Scripture Editor slot, but if
    // somehow none exists we open a new one rather than throwing.
    return { kind: 'open-new' };
  }

  // Power mode (or unset). Behavior is unchanged from the pre-session original:
  if (existingTabIdToReplace) {
    return { kind: 'replace-tab', targetTabId: existingTabIdToReplace };
  }
  const emptyEditor = allScriptureEditors.find((def) => !def.projectId);
  if (emptyEditor) {
    return { kind: 'replace-tab', targetTabId: emptyEditor.id };
  }
  return { kind: 'open-new' };
}

// #endregion Open Editor Dispatch

// #region Open Project Filter

/** Which project-selection dialog the caller is populating. */
export type OpenProjectDialogMode = 'resourceViewer' | 'scriptureEditor';

/**
 * Filter a list of projects (paired with their `platform.isPublished` value) to those that belong
 * in the project-selection dialog for a given open mode.
 *
 * Used by the `open()` flow in `main.ts` when no `projectId` is supplied and we need to populate
 * the Scripture Editor / Resource Viewer project picker. The rule is:
 *
 * - `'resourceViewer'` → include projects where `isPublished === true`. The Resource Viewer lists
 *   published references / resources.
 * - `'scriptureEditor'` → include projects where `isPublished === false`. The Scripture Editor lists
 *   unpublished projects.
 *
 * Pure function — does not touch PAPI. The caller is responsible for fetching each project's
 * `platform.isPublished` setting beforehand.
 *
 * @param projectsWithIsPublished List of projects, each with their `platform.isPublished` setting
 *   value already fetched.
 * @param mode Which dialog the caller is populating — see {@link OpenProjectDialogMode}.
 * @returns Project IDs that match the requested open mode, in the original input order.
 */
export function selectProjectIdsForOpenMode(
  projectsWithIsPublished: ReadonlyArray<{ projectId: string; isPublished: boolean }>,
  mode: OpenProjectDialogMode,
): string[] {
  const wantPublished = mode === 'resourceViewer';
  return projectsWithIsPublished
    .filter(({ isPublished }) => isPublished === wantPublished)
    .map(({ projectId }) => projectId);
}

// #endregion Open Project Filter

// #region Default Active Project Picker

/**
 * Outcome of a single picker attempt. Every outcome other than `'filled'` is a "may retry on the
 * next trigger" — the driver in {@link startDefaultProjectPicker} re-invokes on web-view-open,
 * sync-completion and project-set-change events, so transient causes (sync still in flight, layout
 * not loaded yet) clear themselves naturally.
 *
 * - `'wrong-mode'` — `platform.interfaceMode` is not `'simple'`; the picker does nothing until it is.
 * - `'no-empty'` — no empty Scripture Editor (no `projectId`) is currently open. The driver may retry
 *   when a new web view opens.
 * - `'no-send-receive'` — `recentlyOpenedProjects` was empty or all entries failed to open, and S/R
 *   is unavailable or hasn't activated yet. Expected on Platform.Bible on first launch (no recents
 *   yet, no S/R). Logged at debug.
 * - `'failed'` — the open command rejected; logged at warn. The driver may retry on the next trigger.
 * - `'no-candidate'` — S/R was reachable, but no shared project is a candidate. Projects with
 *   `editedStatus` of `'new'` (not yet downloaded locally) or `'unregistered'` (limited/provisional
 *   license) are excluded, and so is any project that cannot be opened (see
 *   {@link createUnsupportedProjectIdsCache}). The driver may retry after a sync completes or the
 *   project set changes.
 * - `'filled'` — the picker successfully called the open command for the top candidate.
 */
export type DefaultProjectPickerOutcome =
  | 'wrong-mode'
  | 'no-empty'
  | 'no-send-receive'
  | 'failed'
  | 'no-candidate'
  | 'filled';

/**
 * Try to open the most-recently-used project from the `platformScripture.recentlyOpenedProjects`
 * data provider. Returns `'filled'` if a recent project was successfully opened, or `undefined` if
 * the service is unavailable, the recents list is empty, every recent project is unsupported (see
 * {@link createUnsupportedProjectIdsCache}), or every recent project fails to open (in which case
 * the caller should fall through to the S/R-based picker).
 */
async function tryOpenFromRecentlyOpened(
  papi: typeof PapiBackend,
  unsupportedProjectIds: UnsupportedProjectIdsCache,
): Promise<DefaultProjectPickerOutcome | undefined> {
  try {
    const service = await papi.dataProviders.get('platformScripture.recentlyOpenedProjects');
    if (!service) return undefined;
    // Data-provider getter requires an explicit selector argument, even though the value is ignored.
    const recentProjects = (await service.getRecentProjects(undefined)) ?? [];
    const unsupported = await unsupportedProjectIds.getUnsupportedProjectIds(recentProjects);
    // Try each recent project in order until one opens successfully — in almost all cases the first
    // entry opens and the loop exits immediately. `reduce` with a Promise accumulator is used instead
    // of `for...of + await` to satisfy the no-await-in-loop ESLint rule; each callback awaits the
    // previous result before deciding whether to attempt the next project, so entries are tried
    // sequentially (not in parallel) and the chain short-circuits as soon as one succeeds.
    return recentProjects.reduce(
      async (prev: Promise<DefaultProjectPickerOutcome | undefined>, projectId: string) => {
        const outcome = await prev;
        if (outcome !== undefined) return outcome;
        if (unsupported.has(normalizeProjectId(projectId))) {
          papi.logger.debug(
            `Default active project picker: recent project ${projectId} is unsupported, trying next`,
          );
          return undefined;
        }
        try {
          await papi.commands.sendCommand('platformScriptureEditor.openScriptureEditor', projectId);
          papi.logger.info(
            `Default active project picker: opened recently-used project=${projectId}`,
          );
          try {
            await service.recordProjectOpened(projectId);
          } catch (e) {
            papi.logger.warn(
              `Default active project picker: failed to record recently-opened project ${projectId}: ${getErrorMessage(e)}`,
            );
          }
          return 'filled' as const;
        } catch (e) {
          papi.logger.debug(
            `Default active project picker: recent project ${projectId} failed to open, trying next (${getErrorMessage(e)})`,
          );
          return undefined;
        }
      },
      Promise.resolve<DefaultProjectPickerOutcome | undefined>(undefined),
    );
  } catch (e) {
    papi.logger.debug(
      `Default active project picker: recentlyOpenedProjects unavailable; skipping recents (${getErrorMessage(e)})`,
    );
    return undefined;
  }
}

/**
 * Attempt to fill the empty Scripture Editor in the simple layout with the most-recently-active
 * project. Candidates come first from `recentlyOpenedProjects` (tried in order, most-recent first);
 * `paratextBibleSendReceive.getSharedProjects` is the fallback when recents is empty or all entries
 * fail to open. A project that cannot be opened (see {@link createUnsupportedProjectIdsCache}) is
 * never picked, from either source, however recent. The picker partitions remaining candidates by
 * `canUserEditScripture` and prefers editable projects, falling back to the most-recently-S/R'd
 * Observer-only project so an Observer-only user is not stranded with an empty editor (Observer
 * projects are otherwise reachable via the project switcher).
 *
 * Idempotent: each invocation re-reads the dock and the shared-projects list. The driver in
 * {@link startDefaultProjectPicker} is responsible for re-invoking on events that change those
 * inputs (web-view opens, sync completions, project-set changes).
 *
 * @param papi The PAPI backend handle. Injected for testability.
 * @param unsupportedProjectIds Which projects cannot be opened. The driver passes one that lives as
 *   long as it does; by default each run looks up once.
 * @returns The outcome of this attempt — see {@link DefaultProjectPickerOutcome}.
 */
export async function openDefaultActiveProjectIfApplicable(
  papi: typeof PapiBackend,
  unsupportedProjectIds: UnsupportedProjectIdsCache = createUnsupportedProjectIdsCache(papi),
): Promise<DefaultProjectPickerOutcome> {
  const interfaceMode = await papi.settings.get('platform.interfaceMode');
  if (isPlatformError(interfaceMode)) {
    papi.logger.warn(
      `Default active project picker: failed to read platform.interfaceMode (${getErrorMessage(interfaceMode)}); returning 'wrong-mode'`,
    );
    return 'wrong-mode';
  }
  if (interfaceMode !== 'simple') return 'wrong-mode';

  const openWebViews = await papi.webViews.getAllOpenWebViewDefinitions();
  const emptyEditor = openWebViews.find(
    (def) => def.webViewType === SCRIPTURE_EDITOR_WEBVIEW_TYPE && !def.projectId,
  );
  if (!emptyEditor) return 'no-empty';

  // Before consulting S/R, try the recently-opened-projects list. If a recent project opens
  // successfully, return immediately without touching the S/R service at all.
  const recentsOutcome = await tryOpenFromRecentlyOpened(papi, unsupportedProjectIds);
  if (recentsOutcome !== undefined) return recentsOutcome;

  // Try `paratextBibleSendReceive.getSharedProjects` directly. If S/R hasn't activated yet (cold
  // start, picker fires inside `platformScriptureEditor.activate()` before `paratextBibleSendReceive`
  // registers commands) or isn't installed at all (Platform.Bible), this rejects and we return
  // `'no-send-receive'`. The driver's existing triggers handle the retry once S/R is ready — we
  // do NOT block here. paratextBibleSendReceive registers commands but no network object of its
  // own, so `papi.networkObjectStatus.waitForNetworkObject` has nothing to wait on; PAPI exposes no
  // equivalent "is this command registered yet?" signal, which is why this probes and gives up
  // rather than waiting.
  let sharedProjects: SharedProjectsInfo;
  try {
    sharedProjects = await papi.commands.sendCommand('paratextBibleSendReceive.getSharedProjects');
  } catch (e) {
    // Expected steady state on Platform.Bible (S/R absent) and transient on paratext-10-studio
    // cold start. Debug-level — info would be noisy because this fires on every picker run on
    // Platform.Bible.
    papi.logger.debug(
      `Default active project picker: getSharedProjects unavailable; returning 'no-send-receive' (${getErrorMessage(e)})`,
    );
    return 'no-send-receive';
  }

  // Exclude `'new'` (not yet downloaded — can't be opened) and `'unregistered'` (limited/provisional
  // license — surprising to auto-open as the default). Projects with no `lastSendReceiveDate` are
  // kept as candidates — a Power-created project that has never been S/R'd, or one copied onto the
  // machine manually, is still a valid project to auto-open. `sortByRecency` treats missing or
  // unparseable dates as epoch (0), so any S/R'd project still wins; never-synced projects only
  // become the top candidate when nothing else qualifies.
  const filtered = Object.values(sharedProjects).filter(
    (info) => info.editedStatus !== 'new' && info.editedStatus !== 'unregistered',
  );

  const unsupported = await unsupportedProjectIds.getUnsupportedProjectIds(
    filtered.map((info) => info.id),
  );
  const openable = filtered.filter((info) => !unsupported.has(normalizeProjectId(info.id)));

  // Annotate each surviving candidate with the current user's role. Per-candidate PDP lookups or
  // method rejections are treated as Observer-equivalent — they fall to the `observerOnly` group
  // and only matter if no editable candidate exists. A missing PDP (e.g., a project that doesn't
  // advertise `platformScripture.scriptureEditPermissions`) is likewise Observer-equivalent.
  // Mirrors the C# method's "false on exception" semantics.
  const annotated = await Promise.all(
    openable.map(async (info) => {
      try {
        const pdp = await papi.projectDataProviders.get(
          'platformScripture.scriptureEditPermissions',
          info.id,
        );
        if (!pdp) return { info, canEdit: false };
        return { info, canEdit: await pdp.canUserEditScripture() };
      } catch {
        return { info, canEdit: false };
      }
    }),
  );

  // `lastSendReceiveDate` is produced by .NET upstream and isn't format-guaranteed in the type, so
  // parse to a timestamp rather than relying on lexicographic ISO ordering. Missing or unparseable
  // dates are treated as epoch (0) so they sort to the end — any S/R'd project beats a
  // never-synced one.
  const toTimestamp = (date: string) => {
    if (!date) return 0;
    const t = new Date(date).getTime();
    return Number.isNaN(t) ? 0 : t;
  };
  const sortByRecency = (
    a: { info: { lastSendReceiveDate: string } },
    b: { info: { lastSendReceiveDate: string } },
  ) => toTimestamp(b.info.lastSendReceiveDate) - toTimestamp(a.info.lastSendReceiveDate);

  const editable = annotated.filter((a) => a.canEdit).sort(sortByRecency);
  const observerOnly = annotated.filter((a) => !a.canEdit).sort(sortByRecency);

  // Prefer the most-recently-S/R'd editable project. When the user has only Observer-only projects,
  // still open the most-recently-S/R'd one — Observer projects are otherwise reachable via the
  // project switcher, so we shouldn't strand an Observer-only user with an empty editor.
  const topCandidate = editable[0] ?? observerOnly[0];

  if (!topCandidate) return 'no-candidate';

  const top = topCandidate.info;
  let hasFailed = false;
  let openedScriptureEditor = false;
  papi.logger.info(`Default active project picker: opening project=${top.id}`);
  try {
    await papi.commands.sendCommand('platformScriptureEditor.openScriptureEditor', top.id);
    openedScriptureEditor = true;
  } catch (e) {
    papi.logger.warn(
      `Default active project picker: openScriptureEditor for ${top.id} failed: ${getErrorMessage(e)}`,
    );
    hasFailed = true;
  }

  // Best-effort: record the project in the recent projects list so the future Recent projects picker
  // can surface it. Failure here must NOT change the outcome — opening succeeded.
  if (openedScriptureEditor) {
    try {
      const recentlyOpenedProjects = await papi.dataProviders.get(
        'platformScripture.recentlyOpenedProjects',
      );
      await recentlyOpenedProjects?.recordProjectOpened(top.id);
    } catch (e) {
      papi.logger.warn(
        `Default active project picker: failed to record recently-opened project ${top.id}: ${getErrorMessage(e)}`,
      );
    }
  }

  return hasFailed ? 'failed' : 'filled';
}

/**
 * Subscribe to the events that change the default-project picker's inputs, and run the picker each
 * time one fires. Returns an unsubscriber that closes every subscription.
 *
 * Triggers:
 *
 * - `webViews.onDidOpenWebView` — handles a late-arriving empty Scripture Editor (the layout's
 *   placeholder may not be in the dock yet at activate time).
 * - `webViews.onDidUpdateWebView` — handles soft-close-then-reopen on macOS (red button hides the
 *   window but keeps the extension host alive). The layout-restore path can re-create the Scripture
 *   Editor without a `projectId`, and from the extension host's perspective the webview was "always
 *   there" — so `onDidOpenWebView` doesn't re-fire. `onDidUpdateWebView` fires when any webview's
 *   definition changes, including the projectId being reset.
 * - `paratextBibleSendReceive.onSyncStateChanged` (when `isSyncing` is `false`) — handles a sync
 *   finishing. Newly-added shared projects look ineligible (`editedStatus === 'new'`, no
 *   `lastSendReceiveDate`) until the first sync settles, so the picker has to re-check after that.
 * - `platform.onDidChangeProjects` — handles the project set changing, including through the syncs
 *   that raise no `onSyncStateChanged` (see `adr-toolbar-sync-status-is-local`). It also fires when
 *   a project's metadata changes (a rename, its language, whether it is editable), which re-runs
 *   the picker for nothing. Once the editor has a project, such a run exits early (`'no-empty'`).
 *   While an empty editor exists, each one repeats the recently-opened lookup,
 *   `paratextBibleSendReceive.getSharedProjects`, a permission lookup per candidate and the lookup
 *   of which candidates cannot be opened; that is bounded by the emitter's debounce and by the
 *   coalescing below. Not debounced here: its emitter (`LocalParatextProjects`, C#) already
 *   debounces it.
 *
 * Cold-start gap: there is no explicit "S/R command registered" signal, so if
 * `paratextBibleSendReceive` activates after `platformScriptureEditor` but before any of the
 * triggers above fires, the picker sits idle until one does. Webview and sync activity at startup
 * cover this in practice.
 *
 * The picker is idempotent: each call re-reads the dock and the shared-projects list and quietly
 * does nothing when there is nothing to do (editor already filled, wrong interface mode, no
 * eligible project yet). At most one run is in flight at a time; concurrent triggers coalesce into
 * a single follow-up run.
 *
 * Whether a candidate can be opened is looked up once for the driver's lifetime, and again only
 * after `platform.onDidChangeProjects`, a project data provider factory registering, or a failed
 * lookup's retry delay, since a user whose every candidate is unsupported keeps an empty editor,
 * and so re-runs the picker, on every trigger.
 *
 * After a `'no-candidate'` run, the web-view triggers are skipped until something that can add a
 * candidate happens: a sync ending, `platform.onDidChangeProjects`, a project data provider factory
 * registering, or a Scripture Editor showing a project (which records it as recent). Each skipped
 * run would otherwise ask for the shared projects again for the same answer.
 *
 * Mirrors the simple-function pattern used in `home.web-view.tsx` rather than a class wrapper.
 */
export function startDefaultProjectPicker(papi: typeof PapiBackend): Unsubscriber {
  // 'running-with-retry-queued' captures the case where a trigger fires while a tryPicker call is
  // in flight. The in-flight attempt may have observed stale inputs before the trigger materialized;
  // the `finally` block re-fires once to close that race. A single string union (rather than two
  // booleans) makes the impossible 'idle + retry-queued' combination unrepresentable; see
  // Code-Style-Guide.md "Prefer string unions over multiple interdependent booleans".
  let pickerState: 'idle' | 'running' | 'running-with-retry-queued' = 'idle';
  const unsupportedProjectIds = createUnsupportedProjectIdsCache(papi);
  // Read via a helper to defeat TypeScript's flow narrowing — the listeners below can mutate
  // pickerState concurrently across awaits, which TS's flow analysis can't model.
  const getPickerState = () => pickerState;
  // Bumped by each event that can add a candidate. A run that found none records the version it
  // started at, so an event landing while it is in flight is not swallowed by its result.
  let candidateInputsVersion = 0;
  let noCandidateAtVersion: number | undefined;
  const candidateInputsChanged = () => {
    candidateInputsVersion += 1;
  };
  /** Whether a web view opening or updating should run the picker. */
  const shouldRunForWebView = (webView: SavedWebViewDefinition) => {
    if (webView.webViewType === SCRIPTURE_EDITOR_WEBVIEW_TYPE && webView.projectId)
      candidateInputsChanged();
    return noCandidateAtVersion !== candidateInputsVersion;
  };

  const tryPicker = async (): Promise<void> => {
    if (pickerState !== 'idle') {
      pickerState = 'running-with-retry-queued';
      return;
    }
    pickerState = 'running';
    const versionAtStart = candidateInputsVersion;
    try {
      const outcome = await openDefaultActiveProjectIfApplicable(papi, unsupportedProjectIds);
      noCandidateAtVersion = outcome === 'no-candidate' ? versionAtStart : undefined;
      if (outcome !== 'filled') {
        papi.logger.debug(
          `Default active project picker: unexpected outcome received: '${outcome}'`,
        );
      }
    } catch (e) {
      // `openDefaultActiveProjectIfApplicable` catches its own errors and returns 'failed'; this
      // catch only fires on unexpected throws (e.g. PAPI plumbing bugs).
      noCandidateAtVersion = undefined;
      papi.logger.warn(
        `Default active project picker: tryPicker threw unexpectedly: ${getErrorMessage(e)}`,
      );
    } finally {
      const wasRetryQueued = getPickerState() === 'running-with-retry-queued';
      pickerState = 'idle';
      // Fire-and-forget follow-up to close the race window. `tryPicker` catches its own errors,
      // so the `.catch` here is defensive against a future change that could leak a rejection.
      if (wasRetryQueued)
        tryPicker().catch((e) =>
          papi.logger.warn(
            `Default active project picker: coalesced retry threw unexpectedly: ${getErrorMessage(e)}`,
          ),
        );
    }
  };

  // `tryPicker()` catches its own errors internally; the `.catch` blocks below are defensive
  // against a future change that could leak a rejection — matches the `finally`-block retry above.
  const unsubFromWebViewOpen = papi.webViews.onDidOpenWebView(({ webView }) => {
    if (!shouldRunForWebView(webView)) return;
    tryPicker().catch((e) =>
      papi.logger.warn(
        `Default active project picker: webView-open handler threw unexpectedly: ${getErrorMessage(e)}`,
      ),
    );
  });

  const unsubFromWebViewUpdate = papi.webViews.onDidUpdateWebView(({ webView }) => {
    // Only Scripture Editor updates can change the picker's outcome — any other webview's update
    // can't reveal or remove an empty editor.
    if (webView.webViewType !== SCRIPTURE_EDITOR_WEBVIEW_TYPE || !shouldRunForWebView(webView))
      return;
    tryPicker().catch((e) =>
      papi.logger.warn(
        `Default active project picker: webView-update handler threw unexpectedly: ${getErrorMessage(e)}`,
      ),
    );
  });

  const unsubFromSync = papi.network.getNetworkEvent<{ isSyncing: boolean }>(
    'paratextBibleSendReceive.onSyncStateChanged',
  )(({ isSyncing }) => {
    if (isSyncing) return;
    candidateInputsChanged();
    tryPicker().catch((e) =>
      papi.logger.warn(
        `Default active project picker: sync-state handler threw unexpectedly: ${getErrorMessage(e)}`,
      ),
    );
  });

  const unsubFromProjectsChanged = papi.network.getNetworkEvent('platform.onDidChangeProjects')(
    () => {
      unsupportedProjectIds.invalidate();
      candidateInputsChanged();
      tryPicker().catch((e) =>
        papi.logger.warn(
          `Default active project picker: projects-changed handler threw unexpectedly: ${getErrorMessage(e)}`,
        ),
      );
    },
  );
  // A factory that registers late changes which projects are known, but raises no projects-changed
  // event. Invalidating only drops held answers, so a burst of registrations costs no lookups.
  const unsubFromNetworkObjectCreated = papi.network.getNetworkEvent(
    'object:onDidCreateNetworkObject',
  )(({ objectType }) => {
    if (objectType !== PDP_FACTORY_OBJECT_TYPE) return;
    unsupportedProjectIds.invalidate();
    candidateInputsChanged();
  });

  // Cover the case where the empty editor and an eligible synced project are already in place
  // (e.g., second startup after a successful first run).
  tryPicker().catch((e) =>
    papi.logger.warn(
      `Default active project picker: initial run threw unexpectedly: ${getErrorMessage(e)}`,
    ),
  );

  return aggregateUnsubscribers([
    unsubFromWebViewOpen,
    unsubFromWebViewUpdate,
    unsubFromSync,
    unsubFromProjectsChanged,
    unsubFromNetworkObjectCreated,
  ]);
}

// #endregion Default Active Project Picker

// #region Project-Switch Sync

/**
 * Fire-and-forget helper that flushes the outgoing project, then syncs the incoming one. Each sync
 * is independently error-isolated so a failure in one doesn't block the other. Called after a
 * Simple-mode replace-tab project switch, and by `finalizeProjectSwitch` after a Power -> Simple
 * mode switch — by which time the user may be back in Power mode.
 *
 * Uses `paratextBibleSendReceive.syncProjects` for the incoming project because it also pulls
 * connected resources and translation partners (deep sync). Uses the shallower
 * `paratextBibleSendReceive.sendReceiveProjects` for the outgoing project because we only need to
 * flush any local edits — a full deep sync is unnecessary on the way out.
 *
 * The incoming project syncs LAST because these are two separate backend runs and the sync
 * indicator reports the most recent one. Whichever runs last is the verdict the user is shown, and
 * the project they just switched to — the one on screen — is what that verdict should describe. A
 * failure flushing the outgoing project reaches the user only through its own failure toast (see
 * below), not the indicator; see `adr-sync-activity-outcome-is-coarse` in
 * `.context/standards/Architecture-Decisions.md`.
 *
 * The outgoing sync is skipped only for a published resource (see `isProjectPublished`), which
 * holds nothing the user wrote. A translation project with editing switched off still syncs: its
 * Scripture text is locked, but the user can still add comments to it. The window-close and
 * shutdown syncs (`getWritableEditorProjectIds` in `src/main/shutdown-tasks.ts`) do not yet draw
 * the same line: they drop every editor whose saved `isReadOnly` is set, and an editor opened with
 * a project ID (Home, New Tab, the title-bar picker) takes that flag from `platform.isEditable`, so
 * an `Editable=F` project is synced here but not when its window closes or the app quits
 * (PT-4786).
 *
 * `interfaceMode` is the caller's read of `platform.interfaceMode` (`undefined` when that read
 * failed). The incoming sync suppresses the dotnet progress toast only for a known `'simple'`,
 * where the toolbar sync indicator is its surface; any other value keeps the toast, since the
 * indicator may not be mounted. The flag is sent only when it is `true`: a dotnet `SyncProjects`
 * that predates the parameter rejects a two-argument call, so omitting it keeps the toast-keeping
 * cases working against that backend. The outgoing `sendReceiveProjects` keeps its toast: its
 * `suppressNotification` would also hide the failure toast, which is this claimless sync's only
 * failure surface.
 *
 * Gated on first-run sync consent: neither Send/Receive command runs unless the
 * `platform.getAutomaticSyncConsent` command answers `granted`. That command is the main process's
 * `getAutomaticSyncConsent`, the one implementation of the rule, so this module does not restate
 * it. The gate covers those two commands only — this module still reaches the network elsewhere
 * during the wizard, e.g. `openDefaultActiveProjectIfApplicable`'s
 * `paratextBibleSendReceive.getSharedProjects` registry lookup (see PT-4606).
 *
 * The gate applies in Simple mode only, so it checks `interfaceMode` rather than trusting every
 * caller to be Simple-mode-only. An unreadable mode (`undefined`) is treated as Simple, so it
 * cannot bypass the gate.
 */
export async function syncOnProjectSwitch(
  papi: typeof PapiBackend,
  incomingProjectId: string,
  outgoingProjectId: string | undefined,
  interfaceMode: SettingTypes['platform.interfaceMode'] | undefined,
): Promise<void> {
  // The first-run wizard is an overlay, so the project picker behind it can drive a switch through
  // here before the user has answered its sync-consent step.
  if (interfaceMode !== 'power') {
    let consent;
    try {
      consent = await papi.commands.sendCommand('platform.getAutomaticSyncConsent');
    } catch (e) {
      papi.logger.warn(
        `Project-switch sync: could not check first-run sync consent (${getErrorMessage(e)}); skipping sync`,
      );
      return;
    }
    if (consent !== 'granted') {
      papi.logger.info(`Project-switch sync skipped: first-run sync consent is ${consent}`);
      return;
    }
  }

  if (outgoingProjectId && !(await isProjectPublished(papi, outgoingProjectId))) {
    try {
      await papi.commands.sendCommand('paratextBibleSendReceive.sendReceiveProjects', [
        outgoingProjectId,
      ]);
    } catch (e) {
      papi.logger.warn(
        `Project-switch sync: outgoing sync for ${outgoingProjectId} failed: ${getErrorMessage(e)}`,
      );
    }
  }

  try {
    // Mode change mid-sync: intentionally not handled. The flag is fixed for the run, and the
    // toolbar indicator mounts only in Simple mode, so switching to Power while a suppressed sync
    // runs leaves it with no progress surface until it ends. Accepted in
    // `adr-sync-surface-per-interface-mode`.
    const flag: [true] | [] = interfaceMode === 'simple' ? [true] : [];
    await papi.commands.sendCommand(
      'paratextBibleSendReceive.syncProjects',
      [incomingProjectId],
      ...flag,
    );
  } catch (e) {
    papi.logger.warn(
      `Project-switch sync: incoming sync for ${incomingProjectId} failed: ${getErrorMessage(e)}`,
    );
  }
}

/**
 * How long {@link waitForUnsentChanges} keeps listening, once no sync is running, for a project to
 * be reported as holding changes to send. Well past the backend's debounce after a project's last
 * write plus its repository check, so an edit whose save was still on its way when the wait began
 * is still seen.
 */
export const UNSENT_CHANGES_GRACE_MS = 10_000;

/**
 * Upper bound on how long {@link waitForUnsentChanges} waits for a running sync, and the recheck
 * after it, to finish before giving up without an answer. Long, because a sync can take minutes.
 */
export const UNSENT_CHANGES_SYNC_WAIT_MS = 10 * 60_000;

/** Attempts to read the unsynced-changes snapshot. A cold-start rejection must be retried. */
const UNSYNCED_CHANGES_SEED_ATTEMPTS = 5;
const UNSYNCED_CHANGES_SEED_RETRY_MS = 1_000;

/**
 * Checks only the fields {@link waitForUnsentChanges} reads. The renderer and Home keep guards of
 * their own, which this extension cannot import.
 */
function isUnsyncedChangesSnapshot(value: unknown): value is UnsyncedChangesSnapshot {
  if (typeof value !== 'object' || !value) return false;
  if (!('toSend' in value) || !Array.isArray(value.toSend)) return false;
  return value.toSend.every(isString);
}

/**
 * Whether a project holds local changes this user's next Send/Receive would send, read from the
 * backend's `paratextBibleSendReceive.onUnsyncedChangesChanged` signal.
 *
 * One read is not enough: the backend checks a project a short while after its last write, and
 * while a sync is running (`isRechecking`) the list may predate it, still naming projects that sync
 * is sending. So this ignores the list while a sync is running; once none is, it answers `true` as
 * soon as a snapshot lists the project, or `false` after {@link UNSENT_CHANGES_GRACE_MS} without
 * one. Callers should not block on it.
 *
 * @param papi Backend PAPI instance.
 * @param projectId The project to ask about.
 * @returns `true` if the project has changes to send, `false` if it has none, or `undefined` if no
 *   snapshot could be read or a running sync did not finish within
 *   {@link UNSENT_CHANGES_SYNC_WAIT_MS}.
 */
export async function waitForUnsentChanges(
  papi: typeof PapiBackend,
  projectId: string,
): Promise<boolean | undefined> {
  const normalizedProjectId = normalizeProjectId(projectId);
  return new Promise((resolve) => {
    let isAnswered = false;
    let hasReceivedEvent = false;
    let graceTimer: ReturnType<typeof setTimeout> | undefined;
    let settleTimer: ReturnType<typeof setTimeout> | undefined;
    let unsubscribe: Unsubscriber | undefined;

    const answer = (hasUnsentChanges: boolean | undefined) => {
      if (isAnswered) return;
      isAnswered = true;
      clearTimeout(graceTimer);
      clearTimeout(settleTimer);
      unsubscribe?.();
      resolve(hasUnsentChanges);
    };

    settleTimer = setTimeout(() => {
      papi.logger.warn(
        `Could not tell whether ${projectId} has changes to send: a sync was still running after ${UNSENT_CHANGES_SYNC_WAIT_MS}ms`,
      );
      answer(undefined);
    }, UNSENT_CHANGES_SYNC_WAIT_MS);

    const consider = (snapshot: unknown) => {
      if (!isUnsyncedChangesSnapshot(snapshot)) {
        papi.logger.warn('The unsynced-changes snapshot had an unexpected shape; ignoring it');
        return;
      }
      if (snapshot.isRechecking === true) {
        clearTimeout(graceTimer);
        graceTimer = undefined;
        return;
      }
      if (snapshot.toSend.some((id) => normalizeProjectId(id) === normalizedProjectId)) {
        answer(true);
        return;
      }
      graceTimer ??= setTimeout(() => answer(false), UNSENT_CHANGES_GRACE_MS);
    };

    // Subscribed before the seed is read, so no change can land between the two unseen
    try {
      unsubscribe = papi.network.getNetworkEvent(
        'paratextBibleSendReceive.onUnsyncedChangesChanged',
      )((snapshot) => {
        if (isUnsyncedChangesSnapshot(snapshot)) hasReceivedEvent = true;
        consider(snapshot);
      });
    } catch (e) {
      papi.logger.warn(
        `Could not tell whether ${projectId} has changes to send: could not subscribe to the unsynced-changes signal: ${getErrorMessage(e)}`,
      );
      answer(undefined);
      return;
    }

    let lastSeedError: unknown;
    const readSeed = async (): Promise<UnsyncedChangesSnapshot | undefined> => {
      try {
        const snapshot = await papi.commands.sendCommand(
          'paratextBibleSendReceive.getUnsyncedChanges',
        );
        if (isUnsyncedChangesSnapshot(snapshot)) return snapshot;
        lastSeedError = new Error('the unsynced-changes snapshot had an unexpected shape');
      } catch (e) {
        lastSeedError = e;
      }
      return undefined;
    };

    (async () => {
      const seed = await retryUntil(
        readSeed,
        (snapshot) => snapshot !== undefined || isAnswered || hasReceivedEvent,
        { maxAttempts: UNSYNCED_CHANGES_SEED_ATTEMPTS, delayMs: UNSYNCED_CHANGES_SEED_RETRY_MS },
      );
      // An event that arrived meanwhile is newer than the seed
      if (isAnswered || hasReceivedEvent) return;
      if (seed) {
        consider(seed);
        return;
      }
      papi.logger.warn(
        `Could not tell whether ${projectId} has changes to send: ${getErrorMessage(lastSeedError)}`,
      );
      answer(undefined);
    })();
  });
}

/**
 * Projects whose switch-to-Power sync is still deciding whether to send, by normalized id. A second
 * switch for the same project joins the first instead of deciding separately: both would see the
 * same snapshot and start two overlapping syncs, which the backend refuses.
 */
const projectIdsDecidingSyncOnSwitchToPower = new Set<string>();

/**
 * After a switch from Simple to Power mode, sends what was typed in Simple. Send/receives the
 * project only when {@link waitForUnsentChanges} answers `true`, since a sync with nothing to send
 * would show notifications for no reason. No `suppressNotification`, so Power mode's progress and
 * failure toasts show. Never rejects.
 *
 * Skipped when:
 *
 * - The user chose "Don't sync yet" this session (`deferred`), the first-run flag cannot be read
 *   (`unreadable`), or the consent request rejects. Asked before and after the wait for unsent
 *   changes, so a decline during the wait still counts. An `unconfirmed` answer does NOT skip it: a
 *   user who started in Power mode never sees the wizard that records consent. See
 *   `adr-switch-to-power-sends-unsent-changes`.
 * - The mode no longer reads `'power'` when the sync would start: the switch back to Simple makes its
 *   own (consent-gated) sync decision, and anything still unsent goes on the next switch to Power.
 * - The saved internet setting turns Send/Receive off (`VpnRequired` or `Disabled`). Whether the
 *   machine is actually online cannot be known without trying, so offline is left to the sync's own
 *   failure notification.
 * - An earlier switch-to-Power sync of the same project is still deciding; it covers this one.
 *
 * @param papi Backend PAPI instance.
 * @param projectId The project the Simple-mode Scripture Editor was showing.
 */
export async function syncOnSwitchToPower(
  papi: typeof PapiBackend,
  projectId: string,
): Promise<void> {
  // Any PAPI client can send the command, so the argument is checked rather than trusted
  if (!isString(projectId)) {
    papi.logger.warn('Switch-to-Power sync: ignoring a project id that is not a string');
    return;
  }
  const normalizedProjectId = normalizeProjectId(projectId);
  if (projectIdsDecidingSyncOnSwitchToPower.has(normalizedProjectId)) {
    papi.logger.info(
      `Switch-to-Power sync of ${projectId} is already deciding; not starting another`,
    );
    return;
  }

  projectIdsDecidingSyncOnSwitchToPower.add(normalizedProjectId);
  let shouldSync: boolean;
  try {
    shouldSync = await shouldSyncOnSwitchToPower(papi, projectId);
  } finally {
    projectIdsDecidingSyncOnSwitchToPower.delete(normalizedProjectId);
  }
  if (!shouldSync) return;

  try {
    await papi.commands.sendCommand('paratextBibleSendReceive.sendReceiveProjects', [projectId]);
  } catch (e) {
    papi.logger.warn(`Switch-to-Power sync of ${projectId} failed: ${getErrorMessage(e)}`);
  }
}

/**
 * The first-run sync consent gate's answer when it lets the switch-to-Power sync run, or
 * `undefined` (logged) when it does not. Only `granted` and `unconfirmed` let it run, so an answer
 * this does not know fails closed.
 */
async function getSwitchToPowerSyncConsent(
  papi: typeof PapiBackend,
): Promise<'granted' | 'unconfirmed' | undefined> {
  let consent;
  try {
    consent = await papi.commands.sendCommand('platform.getAutomaticSyncConsent');
  } catch (e) {
    papi.logger.warn(
      `Switch-to-Power sync: could not check first-run sync consent (${getErrorMessage(e)}); skipping sync`,
    );
    return undefined;
  }
  if (consent === 'granted' || consent === 'unconfirmed') return consent;
  papi.logger.info(`Switch-to-Power sync skipped: first-run sync consent is ${consent}`);
  return undefined;
}

/**
 * The checks {@link syncOnSwitchToPower} makes before it syncs: consent, unsent changes, the mode,
 * the internet setting, and consent again. Logs why it answers `false`.
 */
async function shouldSyncOnSwitchToPower(
  papi: typeof PapiBackend,
  projectId: string,
): Promise<boolean> {
  if (!(await getSwitchToPowerSyncConsent(papi))) return false;

  const hasUnsentChanges = await waitForUnsentChanges(papi, projectId);
  if (hasUnsentChanges !== true) {
    // Logged, not shown, even when it could not tell: the switch itself succeeded, the edits stay
    // on disk for the next sync, and like every other automatic sync's skip there is nothing the
    // user could act on. A sync that runs and fails does show its failure notification.
    papi.logger.info(
      `Switch-to-Power sync skipped: ${hasUnsentChanges === false ? 'no' : 'could not tell whether there are'} changes to send in ${projectId}`,
    );
    return false;
  }

  let interfaceMode: SettingTypes['platform.interfaceMode'] | undefined;
  try {
    interfaceMode = await papi.settings.get('platform.interfaceMode');
  } catch (e) {
    papi.logger.warn(
      `Switch-to-Power sync: could not read platform.interfaceMode (${getErrorMessage(e)}); skipping sync of ${projectId}`,
    );
    return false;
  }
  if (interfaceMode !== 'power') {
    papi.logger.info(
      `Switch-to-Power sync of ${projectId} skipped: the interface mode is ${interfaceMode} now, and that switch decides its own sync`,
    );
    return false;
  }

  const internetUse = await readPermittedInternetUse(papi);
  if (internetUse === 'VpnRequired' || internetUse === 'Disabled') {
    papi.logger.info(
      `Switch-to-Power sync of ${projectId} skipped: the internet setting is ${internetUse}, which turns Send/Receive off`,
    );
    return false;
  }

  // Asked again because the wait above can last minutes, and "Don't sync yet" chosen meanwhile
  // must still stop this sync
  const consent = await getSwitchToPowerSyncConsent(papi);
  if (!consent) return false;
  // Logged at info because every other automatic sync would skip here, so a support log must show
  // why this one ran
  if (consent !== 'granted')
    papi.logger.info(
      `Switch-to-Power sync of ${projectId}: first-run sync consent is ${consent}, which does not stop this sync`,
    );
  return true;
}

/**
 * The saved internet setting, or `undefined` when it cannot be read. Blocked values mirror the
 * backend's `InternetServicesGate.IsBlocked`, which enforces them on every Send/Receive; this check
 * only spares a sync that gate would refuse. So an unreadable setting lets the sync go ahead.
 */
async function readPermittedInternetUse(
  papi: typeof PapiBackend,
): Promise<InternetUse | undefined> {
  try {
    const provider = await papi.dataProviders.get(
      'paratextRegistration.internetSettingsDataProvider',
    );
    if (!provider) throw new Error('the internet settings data provider is not available');
    return (await provider.getInternetSettings(undefined)).permittedInternetUse;
  } catch (e) {
    papi.logger.warn(
      `Switch-to-Power sync: could not read the internet setting (${getErrorMessage(e)}); leaving it to Send/Receive`,
    );
    return undefined;
  }
}

// #endregion Project-Switch Sync

// #region Finalize Project Switch

/**
 * Replays the project-switch side effects that `open()`'s replace-tab dispatch normally performs
 * (S/R sync, admin's shared layout auto-apply, recording recently-opened) — for callers that
 * already know the target project's Scripture Editor tab is showing correctly, where `open()`'s own
 * dispatch resolves to `{ kind: 'focus-existing' }` and returns before any of that runs (see
 * `resolveOpenEditorDispatch`). Used by Platform.Bible core's Power -> Simple mode switch, which
 * bakes `projectId` directly into a cloned layout instead of routing through `open()`.
 *
 * Called non-blocking, well after the switch's overlay has already released (see the caller in
 * `web-view.service-host.ts`), so by the time this actually runs the user may have already switched
 * back to Power mode. Mirrors `open()`'s own `needsOverlay` block (main.ts): the sync is
 * fire-and-forget (`syncOnProjectSwitch` already catches its own errors, and awaiting it here would
 * delay the shared-layout apply and `recordProjectOpened` by however long a deep Send/Receive
 * takes, with `recordProjectOpened` never running at all if the user quits mid-sync); and the mode
 * is read fresh here, once, before the sync, since applying while no longer in Simple mode would
 * wrongly manipulate the Power layout instead of being a no-op.
 *
 * @param papi Backend PAPI instance.
 * @param projectId The project now showing in the Scripture Editor.
 * @param applyForProject Callback invoking `SharedLayoutReceiver.applyForProject`. Injected rather
 *   than imported directly, since the receiver is a stateful instance owned by main.ts.
 */
export async function finalizeProjectSwitch(
  papi: typeof PapiBackend,
  projectId: string,
  applyForProject: ((projectId: string) => Promise<void>) | undefined,
): Promise<void> {
  // Read once, before the sync, so the sync and the Simple-only block below agree on the mode. A
  // failed read leaves `undefined`: the sync then keeps its progress toast and the Simple-only block
  // is skipped, the same as for Power.
  let interfaceMode: SettingTypes['platform.interfaceMode'] | undefined;
  try {
    interfaceMode = await papi.settings.get('platform.interfaceMode');
  } catch (e) {
    papi.logger.warn(
      `finalizeProjectSwitch: could not read platform.interfaceMode for ${projectId}; syncing with the progress toast: ${getErrorMessage(e)}`,
    );
  }
  // There's no outgoing project here since this replaces the whole Simple layout, not one editor
  // tab within it.
  syncOnProjectSwitch(papi, projectId, undefined, interfaceMode);
  if (interfaceMode === 'simple') {
    // Normally a no-op: `runProjectBoundSimpleSwitch` (`src/renderer/services/
    // web-view.service-shard.ts`) bakes `projectId` into every merged supplement tab with
    // `applyProjectIdToTabs` before this runs, so the Text Collection arrives already bound and
    // the call returns at its skip guard. Kept as a safety net for a caller that skips the bake.
    // Ordered before `applyForProject` for the same reason the editor-column switch is: a re-point
    // settles its content before the shared layout picks which tab to front. It swallows its own
    // failures, so no try/catch here.
    await updateRelatedTextCollectionPanel(papi, projectId);
    await applyForProject?.(projectId);
  }
  try {
    const recentlyOpenedProjects = await papi.dataProviders.get(
      'platformScripture.recentlyOpenedProjects',
    );
    await recentlyOpenedProjects?.recordProjectOpened(projectId);
  } catch (e) {
    papi.logger.warn(
      `finalizeProjectSwitch: failed to record recently-opened project ${projectId}: ${getErrorMessage(e)}`,
    );
  }
}

// #endregion Finalize Project Switch

// #region Unsupported Projects

/**
 * The localize key explaining why `projectId` cannot be opened, or `''` when it can.
 *
 * A metadata lookup is a fan-out, so keep this out of reactive loops. Any failure counts as
 * openable, so a transient error never replaces a real project's text with the reason.
 *
 * Asks through an interface every Paratext project serves and only the C# factory provides, so at
 * startup the lookup waits for that factory, whose answer carries the reason, instead of polling
 * whichever factory registered first.
 */
export async function getProjectUnsupportedReason(
  papi: typeof PapiBackend,
  projectId: string,
): Promise<string> {
  try {
    const metadata = await papi.projectLookup.getMetadataForProject(
      projectId,
      'platformScripture.scriptureEditPermissions',
    );
    return metadata.unsupportedReason ?? '';
  } catch (e) {
    papi.logger.warn(
      `Could not look up whether ${projectId} can be opened (${getErrorMessage(e)}); treating it as openable`,
    );
    return '';
  }
}

/**
 * The editor web view state key holding the project's `unsupportedReason`: a localize key, or `''`
 * when the project can be opened. Written by the web view factory, read by the web view.
 */
export const UNSUPPORTED_REASON_WEB_VIEW_STATE_KEY = 'unsupportedReason';

/**
 * The editor web view's state for one build of its definition: `state` with the project's
 * {@link UNSUPPORTED_REASON_WEB_VIEW_STATE_KEY} set last, so a reason carried in by a saved layout
 * or by open options never outlives the project's current metadata.
 *
 * Lives here rather than in the provider so a test can reach it: `main.ts` is the extension entry
 * point, and no test imports it.
 *
 * @param papi The instance of papi to look the project up with.
 * @param projectId The project the view shows, if any; no project means nothing to look up.
 * @param state The rest of the state, already merged from the saved layout and the open options.
 * @returns `state` with the reason applied.
 */
export async function buildScriptureEditorWebViewState(
  papi: typeof PapiBackend,
  projectId: string | undefined,
  state: Record<string, unknown>,
): Promise<Record<string, unknown>> {
  const unsupportedReason = projectId ? await getProjectUnsupportedReason(papi, projectId) : '';
  return { ...state, [UNSUPPORTED_REASON_WEB_VIEW_STATE_KEY]: unsupportedReason };
}

/** Which projects cannot be opened, held across calls. See {@link createUnsupportedProjectIdsCache}. */
export type UnsupportedProjectIdsCache = {
  /**
   * Which of `candidateIds` cannot be opened, as ids normalized with `normalizeProjectId`, so
   * callers must normalize the id they test with too: ids from recents or shared-project lists may
   * differ in case from the metadata's. Looks up only the candidates it holds no answer for, and
   * nothing at all when it holds an answer for every one.
   */
  getUnsupportedProjectIds: (candidateIds: readonly string[]) => Promise<ReadonlySet<string>>;
  /** Drop every held answer, so the next call looks up afresh. */
  invalidate: () => void;
};

/**
 * How long a failed {@link createUnsupportedProjectIdsCache} lookup is answered as "every project
 * openable" before the next call looks up again.
 */
export const UNSUPPORTED_PROJECT_IDS_RETRY_DELAY_MS = 30_000;

/**
 * Holds, per project id, whether it can be opened, until {@link UnsupportedProjectIdsCache}'s
 * `invalidate`. Each lookup names its candidates (`includeProjectIds`), so the lookup service's
 * startup retry applies: while no factory knows any of the named candidates, and only within its
 * startup grace period, it waits for one rather than answering "none". A lookup that names a
 * candidate some factory already knows gets no such wait.
 *
 * A failed lookup counts as its candidates openable until
 * {@link UNSUPPORTED_PROJECT_IDS_RETRY_DELAY_MS} has passed; the first call after that drops every
 * held answer, successes included, and looks up again.
 */
export function createUnsupportedProjectIdsCache(
  papi: typeof PapiBackend,
): UnsupportedProjectIdsCache {
  /** Normalized id → whether that project cannot be opened. Holds the promise, not the value. */
  let isUnsupportedById = new Map<string, Promise<boolean>>();
  let failedAt: number | undefined;
  // Bumped by `invalidate`, so a late failure from a superseded lookup stamps nothing.
  let generation = 0;

  /** The normalized ids among `projectIds` that cannot be opened, or `undefined` on failure. */
  const lookUp = async (projectIds: string[]): Promise<Set<string> | undefined> => {
    const lookupGeneration = generation;
    try {
      const metadata = await papi.projectLookup.getMetadataForAllProjects({
        includeProjectIds: projectIds,
      });
      return new Set(
        metadata.filter((m) => m.unsupportedReason).map((m) => normalizeProjectId(m.id)),
      );
    } catch (e) {
      papi.logger.warn(
        `Could not look up which projects can be opened (${getErrorMessage(e)}); treating them as openable`,
      );
      if (lookupGeneration === generation) failedAt = Date.now();
      return undefined;
    }
  };

  return {
    getUnsupportedProjectIds: async (candidateIds) => {
      // A failure is retried in place after a delay, not held for good nor retried on every call:
      // see `.claude/rules/architecture/provider-lookups-fan-out.md`, rule 3.
      if (
        failedAt !== undefined &&
        Date.now() - failedAt >= UNSUPPORTED_PROJECT_IDS_RETRY_DELAY_MS
      ) {
        isUnsupportedById = new Map();
        failedAt = undefined;
      }
      const unanswered = new Map<string, string>();
      candidateIds.forEach((id) => {
        const normalizedId = normalizeProjectId(id);
        if (!isUnsupportedById.has(normalizedId)) unanswered.set(normalizedId, id);
      });
      if (unanswered.size > 0) {
        const lookup = lookUp([...unanswered.values()]);
        unanswered.forEach((_id, normalizedId) =>
          isUnsupportedById.set(
            normalizedId,
            lookup.then((unsupported) => unsupported?.has(normalizedId) ?? false),
          ),
        );
      }
      const answers = await Promise.all(
        candidateIds.map(async (id) => {
          const normalizedId = normalizeProjectId(id);
          const isUnsupported = await isUnsupportedById.get(normalizedId);
          return isUnsupported ? normalizedId : undefined;
        }),
      );
      return new Set(answers.filter((id): id is string => id !== undefined));
    },
    invalidate: () => {
      generation += 1;
      isUnsupportedById = new Map();
      failedAt = undefined;
    },
  };
}

// #endregion Unsupported Projects

// #region Text Connection Panels

/**
 * Whether `projectId` is a published resource rather than a translation project.
 *
 * `platform.isPublished` is the project-kind classification. `platform.isEditable` is not a
 * substitute: it is a project-wide switch on editing the Scripture text, so a translation project
 * can have it off.
 *
 * Read from the project's `platform.base` PDP rather than `projectLookup.getMetadataForProject`,
 * because the setting is the authoritative value while the metadata field is optional.
 *
 * A failed read counts as "not published", the setting's own default: following a project is
 * recoverable on the next switch, while staying put would leave a panel silently on the outgoing
 * project.
 */
async function isProjectPublished(papi: typeof PapiBackend, projectId: string): Promise<boolean> {
  try {
    const pdp = await papi.projectDataProviders.get('platform.base', projectId);
    return (await pdp.getSetting('platform.isPublished')) === true;
  } catch (e) {
    papi.logger.warn(
      `Could not read platform.isPublished for ${projectId} (${getErrorMessage(e)}); treating it as a translation project`,
    );
    return false;
  }
}

/**
 * Opens or updates the model text and the various views to be displayed in tabs in "column 3" (
 * reference texts, commentaries, comments, Text Collection, etc.) for a project.
 *
 * Every panel here is error-isolated, so one failing panel never stops the rest from being
 * re-pointed. Find is NOT here: it needs the id of the editor web view the switch produces, so it
 * is re-pointed separately by {@link updateRelatedFindPanel} once that editor exists.
 *
 * The Text Collection is the one panel that declines to follow a published resource; see
 * {@link updateRelatedTextCollectionPanel}.
 *
 * @param papi The instance of papi to send the commands
 * @param projectId The id of the project to open the text connections for
 */
export async function openOrUpdateRelatedPanels(
  papi: typeof PapiBackend,
  projectId: string,
): Promise<void> {
  // Started first so the settings round trip overlaps the four panel commands below instead of
  // adding to the switch's latency.
  const isPublishedPromise = isProjectPublished(papi, projectId);
  try {
    await papi.commands.sendCommand('platformScriptureEditor.openModelText', projectId);
  } catch (e) {
    papi.logger.warn(`Error opening model text panel: ${getErrorMessage(e)}`);
  }
  try {
    await papi.commands.sendCommand(
      'platformScriptureEditor.openResourceText',
      'CommentaryResource',
      projectId,
    );
  } catch (e) {
    papi.logger.warn(`Error opening commentary text panel: ${getErrorMessage(e)}`);
  }
  try {
    await papi.commands.sendCommand(
      'platformScriptureEditor.openResourceText',
      'ScriptureResource',
      projectId,
    );
  } catch (e) {
    papi.logger.warn(`Error opening scripture resource text panel: ${getErrorMessage(e)}`);
  }
  try {
    await papi.commands.sendCommand('legacyCommentManager.openCommentListPanel', projectId);
  } catch (e) {
    papi.logger.warn(`Error opening comment list panel: ${getErrorMessage(e)}`);
  }
  // Not wrapped like the four above: this one swallows its own failures (see its TSDoc).
  await updateRelatedTextCollectionPanel(papi, projectId, isPublishedPromise);
}

/**
 * Options the Text Collection panel's provider reads out of its `openWebViewOptions`.
 *
 * `reloadWebView` types its options as `ReloadWebViewOptions`, which carries only `bringToFront` —
 * but both `openWebView` and `reloadWebView` hand their options straight to
 * `IWebViewProvider.getWebView`, so a wider type that structurally satisfies it is how a project
 * change reaches the provider. Declared as a named type rather than passed as an object literal
 * because an inline literal would trip TypeScript's excess-property check.
 *
 * Exported so `scriptureTextGridWebViewProvider` in `main.ts` types its `openWebViewOptions` with
 * this same type, which catches a _rename_ of `projectId` on either side via the object literal's
 * excess-property check. It does NOT catch an omission: `projectId` has to stay optional, so `{
 * bringToFront: false }` still typechecks and the provider's `openWebViewOptions.projectId ??
 * savedWebView.projectId` would quietly fall back to the stale saved id, leaving the panel on the
 * outgoing project with `typecheck` green. `resolveGridProviderProjectId` pins that precedence and
 * `buildScriptureTextGridWebView` is what the provider calls, so both the rule and its use are
 * covered. (Mirrors `FindWebViewOptions`, which Find exports once and uses on both sides.)
 */
export type TextCollectionPanelOptions = OpenWebViewOptions & { projectId?: string };

/**
 * Which project the Text Collection provider should hand its web view.
 *
 * The two halves of the re-point meet here. `openWebViewOptions` is the half a project switch fills
 * in — `updateRelatedTextCollectionPanel` passes the incoming project through `reloadWebView` — and
 * it has to win: preferring the saved definition when a switch supplied a project leaves the panel
 * rendering the outgoing project's texts. `savedWebView.projectId` is what keeps a restored tab, or
 * one re-provided for an unrelated reason, on the project it already had.
 *
 * Extracted from the provider so this precedence is testable: the provider itself lives in
 * `main.ts`, which no test imports, so inline the rule could be inverted and every test would still
 * pass.
 *
 * @param openWebViewOptions Options the caller passed to `openWebView`/`reloadWebView`.
 * @param savedWebView The saved definition being re-provided.
 * @returns The project id to bind the web view to, or `undefined` when neither half names one.
 */
export function resolveGridProviderProjectId(
  openWebViewOptions: TextCollectionPanelOptions,
  savedWebView: Pick<SavedWebViewDefinition, 'projectId'>,
): string | undefined {
  return openWebViewOptions.projectId ?? savedWebView.projectId;
}

/**
 * Re-points the Text Collection panel at `projectId`, the way {@link openOrUpdateRelatedPanels}
 * re-points the rest of Column 3.
 *
 * Re-pointing is a reload, not an in-place `projectId` update, because `papi.webViews` exposes no
 * definition-updating call at all — only a web view can update its _own_ definition
 * (`updateWebViewDefinition` in `WebViewProps`), so from the service side a reload is the only way
 * to change any updatable property, as `reloadWebView`'s own TSDoc says. The grid does not depend
 * on the reload for correctness: it remounts everything that reads admin layout settings through
 * `useBufferedLayoutSetting` whenever its project changes (see `ScriptureTextGridProjectView`),
 * because that hook is NOT safe for consumers that change `projectId` in place (it would keep
 * serving the previous project's held value). Without any re-point the panel would keep rendering
 * the outgoing project's texts indefinitely: an unbound grid seeds itself once from the window's
 * `ActiveEditorProjectId` and keeps that project from then on (see
 * `resolveTextCollectionProjectId`), so only a re-point moves it.
 *
 * Four deliberate constraints:
 *
 * - Never follows a published resource (see `isProjectPublished`): a resource has no collection of
 *   its own, so following it would cost a reload, and the in-memory state it drops, for an empty
 *   panel. The rule lives here rather than in a caller so every re-point path applies it.
 * - Never creates a panel when none is open, unlike the Text Collection's menu command
 *   (`platformScriptureEditor.showTextCollectionPanel`), which does create one on demand. A project
 *   switch closing a tab the user deliberately closed in Power mode, or one the
 *   `platformScriptureEditor.enableScriptureTextGrid` setting has kept from ever existing, is not
 *   something a re-point should reverse — only a direct request to show the panel should create it.
 *   (Both callers are Simple-mode-only — `openOrUpdateRelatedPanels` for an editor-column switch
 *   and `finalizeProjectSwitch` for a Power→Simple one — so this guard is a contract, not a hot
 *   path.)
 * - Skips the reload when the panel already shows `projectId`, because rebuilding the iframe drops
 *   the grid's in-memory React state for no gain. State held through `useWebViewState` —
 *   `viewMode`, per-cell zoom — survives, since a reload reuses the same web view id.
 *
 *   Not all of that loss is cosmetic. The reload destroys the iframe's JS realm, so a DBL install
 *   running in the grid is abandoned mid-flight: `installDblResource` proxies to .NET and completes
 *   regardless, but the continuation that calls `persistUserAddition` dies with the realm, leaving
 *   the resource installed on disk and absent from the collection, with no notification and no log
 *   (the post-await `sourcesRef` check is a staleness re-read, not a liveness check). Recoverable
 *   by re-adding the resource, which then succeeds immediately. TODO(PT-4510): fix in the install
 *   path — persist the addition somewhere that survives a reload.
 * - Never brings the panel to front. This runs as part of re-pointing the whole column, not because
 *   anyone asked for the Text Collection, and the admin's shared layout chooses the front tab
 *   immediately afterward.
 *
 * Never throws: like every panel in {@link openOrUpdateRelatedPanels}, a failure here is logged and
 * swallowed, because the project switch itself has already succeeded by this point.
 *
 * @param papi The instance of papi to read web view definitions with and request the reload from
 * @param projectId The id of the project whose text collection the panel should show
 * @param isPublishedPromise Whether `projectId` is a published resource. A caller that already
 *   started this read passes it in so the round trip overlaps its own work; otherwise it is read
 *   here, and only once a reload is still in question.
 */
export async function updateRelatedTextCollectionPanel(
  papi: typeof PapiBackend,
  projectId: string,
  isPublishedPromise?: Promise<boolean>,
): Promise<void> {
  let existingPanel: SavedWebViewDefinition | undefined;
  try {
    const allOpenDefs = await papi.webViews.getAllOpenWebViewDefinitions();
    existingPanel = allOpenDefs.find((def) => def.webViewType === SCRIPTURE_TEXT_GRID_WEBVIEW_TYPE);
  } catch (e) {
    // The router rejects this outright when any window is unreachable, so this is "what is open is
    // unknown", not "no panel is open" — distinct from the no-panel case below, which is normal.
    papi.logger.error(
      `Text Collection re-point to ${projectId} aborted: could not establish which web views are open (${getErrorMessage(e)}). The panel may still show a previous project.`,
    );
    return;
  }

  // Normalized on both sides, as this module does everywhere else it compares ids: they arrive
  // verbatim from a resource reference while the .NET side canonicalizes to uppercase, so a raw
  // `===` would read a case-differing id as a different project and reload on every switch back —
  // discarding exactly the in-memory state this guard exists to protect.
  if (
    !existingPanel ||
    (existingPanel.projectId !== undefined &&
      normalizeProjectId(existingPanel.projectId) === normalizeProjectId(projectId))
  )
    return;

  if (await (isPublishedPromise ?? isProjectPublished(papi, projectId))) return;

  try {
    // Hidden case: Simple mode shows one Column 3 tab at a time, so this usually lands on an
    // inactive tab. That is fine and needs no catch-up — the reload remounts the panel and its
    // render is entirely data-driven (no geometry reads, no scrollIntoView), so it produces the
    // right content while hidden and is simply revealed when the tab is next activated.
    const options: TextCollectionPanelOptions = { projectId, bringToFront: false };
    const reloadedId = await papi.webViews.reloadWebView(
      SCRIPTURE_TEXT_GRID_WEBVIEW_TYPE,
      existingPanel.id,
      options,
    );
    // `reloadWebView` resolves `undefined` rather than throwing when the definition has gone or the
    // provider declines to supply one. Worth an error rather than silence: a failed re-point is not
    // self-correcting. `projectId` is not in `SAVED_WEBVIEW_DEFINITION_OMITTED_KEYS`, so once any
    // re-point has succeeded the panel's saved definition carries a project and `explicitProjectId`
    // wins in `resolveTextCollectionProjectId` from then on, and nothing but another re-point will
    // move the panel.
    if (reloadedId === undefined)
      papi.logger.error(
        `Text Collection re-point to ${projectId} did not take: reloadWebView returned no id for panel ${existingPanel.id}. The panel is left showing ${existingPanel.projectId ?? 'no project'}.`,
      );
  } catch (e) {
    papi.logger.error(
      `Text Collection re-point to ${projectId} failed for panel ${existingPanel.id}: ${getErrorMessage(e)}. The panel is left showing ${existingPanel.projectId ?? 'no project'}.`,
    );
  }
}

/**
 * Re-points the Find panel at `projectId`, the way {@link openOrUpdateRelatedPanels} re-points the
 * rest of Column 3. Called after the editor's own web view exists because Find caches
 * `editorWebViewId` to select and highlight a clicked result, and a project switch that replaces
 * the editor tab mints a new one.
 *
 * Re-points without opening, like {@link updateRelatedTextCollectionPanel}: a project switch is not
 * a request to open a panel that isn't there.
 *
 * Deliberately has no editability or project-kind condition: Find follows the editor onto a
 * read-only project or a published resource because searching is a read (see
 * `adr-find-follows-editor-to-read-only`).
 *
 * Only Simple mode re-points Find. The mode is read here, fresh, rather than taken from the caller:
 * a project switch can run long enough for the user to change mode mid-way, and reloading Power
 * mode's Find onto the switched project would be wrong.
 *
 * Hidden case: in Simple mode Find's tab is usually inactive when this runs. The reload remounts
 * Find, whose render is data-driven, so it shows the right project when next shown. But a Find that
 * restores a previous search runs it immediately, hidden or not, and the auto-search held back by
 * `useRunWhenVisible` runs again when the tab is shown, so the search, and the clearing of results
 * it starts with, happens twice. A known gap, tracked as PT-4418.
 *
 * Never throws: like every panel in {@link openOrUpdateRelatedPanels}, a failure here is logged and
 * swallowed, because the project switch itself has already succeeded by this point.
 *
 * @param papi The instance of papi to read the interface mode with and send the command
 * @param projectId The id of the project Find should search from now on
 * @param editorWebViewId Id of the editor web view the switch produced
 */
export async function updateRelatedFindPanel(
  papi: typeof PapiBackend,
  projectId: string,
  editorWebViewId: string | undefined,
): Promise<void> {
  try {
    if ((await papi.settings.get('platform.interfaceMode')) !== 'simple') return;
    await papi.commands.sendCommand(
      'platformScripture.updateFindProject',
      projectId,
      editorWebViewId,
    );
  } catch (e) {
    papi.logger.warn(`Error updating find panel project: ${getErrorMessage(e)}`);
  }
}

/**
 * Re-points an open Checks side panel at `projectId`, the Checks counterpart of
 * {@link updateRelatedFindPanel} and called at the same point for the same reason: the panel holds
 * the editor's web view id to focus the editor and select a clicked result, so it needs the id of
 * the editor the switch produced.
 *
 * Creates nothing. In Simple mode Checks joins Column 3 only when the user opens it, and a project
 * switch is not a request to open it.
 *
 * Never follows a published resource (see `isProjectPublished`), the same rule as
 * {@link updateRelatedTextCollectionPanel}: a resource is not something the user checks, so Checks
 * stays on the translation project. A translation project with editing switched off is followed
 * like any other.
 *
 * Only Simple mode re-points Checks, read fresh here for the same reason as in
 * {@link updateRelatedFindPanel}. In Power mode each Checks panel is docked beside the editor it was
 * opened for, so re-pointing "the" open one would retarget whichever editor's panel the probe
 * happened to find.
 *
 * Never throws: a failure here is logged and swallowed, because the project switch itself has
 * already succeeded by this point.
 *
 * @param papi The instance of papi to read the interface mode and project kind with and send the
 *   command
 * @param projectId The id of the project Checks should check from now on
 * @param editorWebViewId Id of the editor web view the switch produced
 */
export async function updateRelatedChecksSidePanel(
  papi: typeof PapiBackend,
  projectId: string,
  editorWebViewId: string | undefined,
): Promise<void> {
  try {
    if ((await papi.settings.get('platform.interfaceMode')) !== 'simple') return;
    if (await isProjectPublished(papi, projectId)) return;
    await papi.commands.sendCommand(
      'platformScripture.updateChecksSidePanelProject',
      projectId,
      editorWebViewId,
    );
  } catch (e) {
    papi.logger.warn(`Error updating checks side panel project: ${getErrorMessage(e)}`);
  }
}

// #endregion Text Connection Panels

// #region Chapter Scaffold Helpers

function containsChapterOrVerseNode(content: MarkerContent[]): boolean {
  return content.some((item) => {
    if (typeof item === 'string') return false;
    if (item.type === 'chapter' || item.type === 'verse') return true;
    return item.content ? containsChapterOrVerseNode(item.content) : false;
  });
}

/**
 * Whether the given chapter-scoped USJ is "effectively blank" — contains neither a chapter-type
 * node nor any verse-type node anywhere in its content tree. Checking for an existing chapter node
 * (not verses alone) matters: a chapter that already has a `\c` marker but zero verses must not be
 * flagged blank, or inserting the scaffold would create a duplicate `\c` node.
 *
 * @param usj The chapter-scoped USJ to check (as returned by the `platformScripture.USJ_Chapter`
 *   PDP's `ChapterUSJ`, i.e. already scoped to a single chapter).
 * @returns `true` if the chapter has no chapter marker and no verses, `false` otherwise.
 */
export function isChapterBlank(usj: Usj): boolean {
  return !containsChapterOrVerseNode(usj.content);
}

/**
 * Whether a resource panel should say the chapter on screen is empty.
 *
 * Chapter 0 is excluded because it is not a chapter. It addresses the book's front matter — `\id`,
 * `\h`, `\toc`, `\mt`, `\ip` — which carries neither a chapter nor a verse node, so
 * {@link isChapterBlank} reports it blank and the message would replace real content the reader can
 * see. It is reachable rather than theoretical: `calculateTopMatch('GEN 0')` yields `chapterNum: 0`
 * and `handleTopMatchSelect` passes it through with `?? 1`, which a 0 survives.
 *
 * Psalm superscriptions and chapter introductions are NOT affected: a chapter carrying a `\d` still
 * carries its `\c` marker, so {@link isChapterBlank} answers `false` on its own.
 *
 * @param usj The chapter-scoped USJ in hand, or `undefined` if none has arrived for this reference.
 * @param chapterNum The chapter number the panel is displaying.
 * @returns `true` only when the panel is showing a real chapter and that chapter is empty.
 */
export function isBlankChapterOnScreen(usj: Usj | undefined, chapterNum: number): boolean {
  return chapterNum > 0 && usj !== undefined && isChapterBlank(usj);
}

/**
 * Builds the Delta operations that insert a blank `\c` + `\v 1..N` scaffold — one chapter marker
 * followed by one verse marker per verse, each with empty text content. Intended for
 * `EditorRef.applyUpdate` when reinstating a chapter number in an effectively-blank chapter.
 *
 * Not for chapter 1: these ops insert at the start of the document, which there is the book's `\id`
 * line. Chapter 1 goes through `EditorRef.insertFirstChapter`; see {@link insertChapterScaffold}.
 *
 * @param chapterNum The chapter number to insert (matching the chapter shown in the BCV control).
 * @param lastVerseNum The last verse number for this chapter, per the project's versification.
 * @returns The Delta operations, in insertion order.
 */
export function buildChapterScaffoldOps(chapterNum: number, lastVerseNum: number): DeltaOp[] {
  const verseOps: DeltaOp[] = [];
  for (let verseNum = 1; verseNum <= lastVerseNum; verseNum += 1) {
    verseOps.push({ insert: { verse: { number: `${verseNum}`, style: 'v' } } });
  }
  return [{ insert: { chapter: { number: `${chapterNum}`, style: 'c' } } }, ...verseOps];
}

/**
 * Whether the "Add Chapter Number" button should be enabled for a chapter with the given last verse
 * number (as returned by `getEndVerse`). `getEndVerse` returns `0` for chapter 0 or any chapter
 * with no versification entry — a reachable case (e.g. front-matter references use `chapterNum:
 * 0`), not just a defensive one — and the button must not render as clickable then.
 *
 * @param lastVerse The chapter's last verse number, from `getEndVerse(book, chapterNum)`.
 * @returns `true` if the button should be enabled, `false` otherwise.
 */
export function canAddChapterNumber(lastVerse: number): boolean {
  return lastVerse > 0;
}

/**
 * Whether a book holds chapters, so the "Add Chapter Number" button can be offered in it. A
 * peripheral book (FRT, INT, BAK, OTH, CNC, GLO, TDX, NDX) never does, and the editor refuses `\c`
 * in one, though the versification gives it chapters and verses. The Extra books (XXA–XXG) hold
 * chapters like any other book. The book and chapter control draws the same line.
 *
 * Upper-cases the id first: `Canon.isExtraMaterial` matches its id list case-sensitively, so a
 * lowercase id would read as a book that holds chapters.
 *
 * @param bookId The book id, e.g. from the current scripture reference.
 */
export function bookHoldsChapters(bookId: string): boolean {
  const upperBookId = bookId.toUpperCase();
  return !Canon.isExtraMaterial(upperBookId) || Canon.extraBooks().includes(upperBookId);
}

/**
 * Whether structure protection disables the "Add Chapter Number" button.
 *
 * Chapter 1 is exempt from the user's own lock so a Simple-mode user, whose structure is locked by
 * default, can start a new book, which holds only its `\id` line. A chapter document can't tell
 * whether later chapters exist, so chapter 1 of a book that starts at a later chapter, such as a
 * partial translation, is exempt too. Adding chapter 1 there is still valid USFM.
 *
 * The team lock has no exemption: an administrator sets it as a rule for the whole team, so a user
 * it binds waits for an administrator to lift it, even to start a book.
 *
 * @param isStructureProtected Whether the project's structure is currently locked, by either lock.
 * @param isTeamLockBinding Whether the administrator's team lock binds this user, as
 *   `useStructureProtectionState` reports it: `true` while that lock's setting is unknown too.
 * @param chapterNum The blank chapter the button would add.
 * @returns `true` if the button must stay disabled.
 */
export function shouldProtectAddChapterNumber(
  isStructureProtected: boolean,
  isTeamLockBinding: boolean,
  chapterNum: number,
): boolean {
  return isTeamLockBinding || (isStructureProtected && chapterNum !== 1);
}

/** Outcome of {@link resolveAddChapterNumberClick} — what a click on the button should do. */
export type AddChapterNumberClickOutcome = 'insert' | 'already-in-flight' | 'no-versification';

/**
 * Decides what a click on the "Add Chapter Number" button should do, given whether a previous
 * click's scaffold insert is still in flight and the chapter's last verse number.
 *
 * - `'already-in-flight'` — a previous click's insert is still working its way through the insert →
 *   save → PDP-echo round trip (~300ms measured), during which the button stays visible and
 *   enabled. Treating this click as a no-op prevents the scaffold from being inserted a second time
 *   (which would write duplicate `\c`/`\v` markers).
 * - `'no-versification'` — `lastVerse <= 0`. `canAddChapterNumber` should already have hidden the
 *   button in this case, so reaching this outcome is a rare defensive fallback, not the normal
 *   path.
 * - `'insert'` — proceed with the scaffold insert.
 *
 * @param isInsertInFlight Whether a previously-triggered insert has not yet completed (i.e. the
 *   chapter has not yet been observed to become non-blank).
 * @param lastVerse The chapter's last verse number, from `getEndVerse(book, chapterNum)`.
 */
export function resolveAddChapterNumberClick(
  isInsertInFlight: boolean,
  lastVerse: number,
): AddChapterNumberClickOutcome {
  if (isInsertInFlight) return 'already-in-flight';
  if (!canAddChapterNumber(lastVerse)) return 'no-versification';
  return 'insert';
}

/**
 * Outcome of {@link insertChapterScaffold}. Anything but `'inserted'` changed nothing:
 *
 * - `'no-editor'` — there was no editor.
 * - `'refused'` — `EditorRef.insertFirstChapter` returned `false` for chapter 1: its document already
 *   holds a chapter, the editor's own `scrRef` is not chapter 1 (it reads that, not the
 *   `chapterNum` passed to {@link insertChapterScaffold}), or its inner editor is not mounted yet.
 * - `'failed'` — the insert threw, and `error` says why.
 */
export type ChapterScaffoldInsertOutcome =
  | { status: 'inserted' | 'no-editor' | 'refused' }
  | { status: 'failed'; error: string };

/**
 * Inserts a blank chapter's `\c` marker and its empty verses. Chapter 1's document also holds the
 * book's `\id` line and front matter, so only the editor can place `\c 1` after them, and only it
 * knows where chapter content starts: it leaves the verses out when that content already holds text
 * or a verse, as a book typed or imported without chapter markers does. A later chapter's scaffold
 * goes at the start of its document.
 *
 * Catches what the editor throws (`insertFirstChapter` does for a read-only editor or one with no
 * scripture reference) and reports it as `'failed'`: an error thrown in a web view's click handler
 * never reaches the app's log.
 *
 * @param editor The editor to insert into, or nothing while it is not mounted.
 * @param chapterNum The blank chapter to add.
 * @param lastVerse The chapter's last verse number, from `getEndVerse(book, chapterNum)`.
 */
export function insertChapterScaffold(
  editor: Pick<EditorRef, 'applyUpdate' | 'insertFirstChapter'> | null | undefined,
  chapterNum: number,
  lastVerse: number,
): ChapterScaffoldInsertOutcome {
  if (!editor) return { status: 'no-editor' };
  try {
    if (chapterNum === 1)
      return { status: editor.insertFirstChapter(lastVerse) ? 'inserted' : 'refused' };
    editor.applyUpdate(buildChapterScaffoldOps(chapterNum, lastVerse), 'local');
    return { status: 'inserted' };
  } catch (error) {
    return { status: 'failed', error: getErrorMessage(error) };
  }
}

// #endregion Chapter Scaffold Helpers

// #region Missing Book Detection
// TODO(PT-4416): Move this region to its own module; this file is a grab-bag of unrelated helpers.

/**
 * Matches the message thrown by C#'s `MissingBookException` (`c-sharp/MissingBookException.cs`),
 * which formats as `Book number {bookNum} not found in project {projectId}.` Unanchored because the
 * PDP layer prefixes its own context onto the message before it reaches a web view.
 *
 * Message matching is the only signal available: the error crosses the PAPI boundary as a
 * `PlatformError`/rejected promise carrying a string, with no structured code to key off. Keep this
 * in lockstep with the C# exception — if that message is ever reworded, every consumer of
 * {@link isMissingBookError} silently starts reporting "book present".
 * `c-sharp-tests/MissingBookExceptionTests.cs` pins the exact wording so the two sides cannot drift
 * apart unnoticed.
 *
 * Deliberately matches on the invariant part of the sentence only, so it still succeeds on a
 * message whose two identities {@link MISSING_BOOK_IDENTITY_REGEX} cannot parse. That is what lets
 * callers with no neutral outcome degrade safely: the main editor's gate is the identity
 * comparison, and an unparseable message would otherwise leave it treating the failure as "book
 * exists" and waiting for USJ that never arrives, so it falls back to this pattern instead.
 * Detection also decides log level (ordinary navigation vs. a real fault) and tells a stale
 * missing-book failure from a genuine error.
 */
const MISSING_BOOK_MESSAGE_REGEX = /Book number \d+ not found in project/;

/**
 * Captures which book and which project a missing-book message names, so a caller can tell "the
 * resource I am showing lacks the book I am showing" from a leftover error about somewhere the user
 * has already navigated away from.
 *
 * The project group is greedy up to the final period because the C# message always terminates with
 * one, so the id runs to the LAST period rather than the first — a project id containing a period
 * survives intact instead of being truncated into an id that compares unequal.
 */
const MISSING_BOOK_IDENTITY_REGEX = /Book number (\d+) not found in project (.+)\./;

/**
 * Reads a PDP failure's message, or `''` for anything that is not one.
 *
 * Structural gate for both predicates below rather than for their callers. `getErrorMessage` falls
 * back to `JSON.stringify` for any object without a string `message`, so handing it a success value
 * serializes the entire chapter USJ on every render and then matches the regex against the
 * scripture text itself. Guarding here means no caller can reach that by passing a raw hook value.
 */
function getMissingBookCandidateMessage(error: unknown): string {
  if (!isPlatformError(error) && !(error instanceof Error) && typeof error !== 'string') return '';
  return getErrorMessage(error);
}

/** The book and project a `MissingBookException` names. */
export type MissingBookErrorInfo = {
  /** The 1-based book number that was not found. */
  bookNum: number;
  /** The id of the project or resource the book was not found in. */
  projectId: string;
};

/**
 * Reads the book and project out of a missing-book failure, or `undefined` if the failure is
 * something else or the message does not carry both identities.
 *
 * Prefer this over {@link isMissingBookError} wherever the caller knows what it is currently
 * displaying: a bare boolean cannot distinguish a live failure from a stale one, because a data
 * hook keeps serving the previous selector's result until the new subscription's first update
 * lands.
 *
 * @param error The error or `PlatformError` to inspect.
 * @returns The book number and project id, or `undefined` for any other failure.
 */
export function parseMissingBookError(error: unknown): MissingBookErrorInfo | undefined {
  const match = MISSING_BOOK_IDENTITY_REGEX.exec(getMissingBookCandidateMessage(error));
  if (!match) return undefined;
  return { bookNum: Number(match[1]), projectId: match[2] };
}

/**
 * Whether a failure from a USJ project data provider means "this book is not in this project or
 * resource" as opposed to a genuine error. Callers use it to swap in a book-not-available view
 * instead of surfacing a failure or, worse, rendering a silently blank editor.
 *
 * Accepts `unknown` so both shapes the error arrives in are covered: a `PlatformError` read off
 * `useProjectData` and a rejection thrown by an imperative `getChapterUSJ` call.
 *
 * This answers only "is it that kind of failure", and answers it for every missing-book message
 * including one whose identities cannot be parsed. A caller that renders a message about the book
 * it is currently showing should use {@link parseMissingBookError} and compare, so a leftover error
 * cannot be attributed to the wrong book.
 *
 * @param error The error or `PlatformError` to inspect.
 * @returns `true` only when the message identifies a missing book; `false` for every other failure,
 *   including no error at all.
 */
export function isMissingBookError(error: unknown): boolean {
  return MISSING_BOOK_MESSAGE_REGEX.test(getMissingBookCandidateMessage(error));
}

/**
 * Whether a failure describes the book AND project a view is displaying right now, and so may be
 * reported to the user as "this book is not in this text".
 *
 * This is the comparison every missing-book surface needs, and the reason a boolean latched when
 * the failure arrived is not good enough. A flag set from an effect or a `catch` is always one
 * render behind: the render that first pairs a new book (or a new project) with the previous result
 * commits before the effect that would clear the flag runs, so that render asserts the message
 * about a book the text does have. Deriving the answer from the failure's own identities makes the
 * wrong frame unrepresentable rather than merely unlikely.
 *
 * Project ids are compared case-insensitively. C# canonicalizes them to uppercase and reports that
 * form in the exception, while a view's own id arrives verbatim from a resource reference or web
 * view state; the PDP lookup folds case, so a casing mismatch is invisible on the data path and
 * would surface only here.
 *
 * @param options.error The value or rejection received from a scripture PDP.
 * @param options.currentBookNum The book number the view is displaying. 0 or less means the view
 *   has no book it can name, so no claim is made about one.
 * @param options.projectId The project or resource id the view is reading from.
 * @returns `true` only when the failure names both the book and the project currently on screen.
 */
export function isMissingBookOnScreen({
  error,
  currentBookNum,
  projectId,
}: {
  error: unknown;
  currentBookNum: number;
  projectId: string | undefined;
}): boolean {
  return isMissingBookInfoOnScreen({
    missingBook: parseMissingBookError(error),
    currentBookNum,
    projectId,
  });
}

/**
 * The comparison half of {@link isMissingBookOnScreen}, for a caller that has already parsed the
 * failure. Use it when the same message would otherwise be parsed more than once for one decision —
 * for example alongside {@link isMissingBookError}, or when the parsed identities are also needed
 * for diagnostics.
 *
 * @param options.missingBook The identities {@link parseMissingBookError} read out of the failure,
 *   or `undefined` if it read none.
 * @param options.currentBookNum The book number the view is displaying. 0 or less means the view
 *   has no book it can name, so no claim is made about one.
 * @param options.projectId The project or resource id the view is reading from.
 * @returns `true` only when the identities name both the book and the project currently on screen.
 */
export function isMissingBookInfoOnScreen({
  missingBook,
  currentBookNum,
  projectId,
}: {
  missingBook: MissingBookErrorInfo | undefined;
  currentBookNum: number;
  projectId: string | undefined;
}): boolean {
  if (!projectId || currentBookNum <= 0) return false;
  return (
    !!missingBook &&
    missingBook.bookNum === currentBookNum &&
    normalizeProjectId(missingBook.projectId) === normalizeProjectId(projectId)
  );
}

/**
 * Whether a parsed project id looks like the on-screen one with extra text swept up after it.
 *
 * The identity capture runs greedily to the terminal period so that project ids containing `.`
 * survive intact, which means a trailing sentence on the same line lands inside the capture (`"ABC.
 * See logs"` for project `ABC`). That leaves a missing-book failure looking like one about a
 * DIFFERENT project — indistinguishable, by comparison alone, from the ordinary case of an error
 * left over from a resource the user just switched away from. This separates the two: only a
 * mis-parse yields a captured id that STARTS with the real one.
 *
 * @param parsedProjectId The project id read out of the message.
 * @param projectId The project id the view is reading from.
 * @returns `true` when the parse looks like an over-run of `projectId` rather than a different
 *   project.
 */
export function isOverrunProjectIdParse(
  parsedProjectId: string,
  projectId: string | undefined,
): boolean {
  if (!projectId) return false;
  const parsed = normalizeProjectId(parsedProjectId);
  const actual = normalizeProjectId(projectId);
  return parsed !== actual && parsed.startsWith(actual);
}

/** What a resource panel (Model text, Bible texts, Commentaries) should show in its content area. */
export type ResourceContentState = 'loading' | 'bookNotAvailable' | 'failed' | 'ready';

/**
 * Decides whether a resource panel shows a spinner, the book-not-available message, a terminal
 * failure message, or its editor.
 *
 * The message is shown only when the failure names BOTH the book and the project the panel is
 * currently displaying. That identity check, rather than any timing signal, is what keeps a stale
 * error from being misattributed: a data hook does not reset to its default when the selector
 * changes — it keeps serving the PREVIOUS selector's result until the new subscription's first
 * update lands — so an error in hand may describe the book the user just left or the resource they
 * just switched away from. Reading it as current would flash "this book is not in this text" on the
 * way INTO a book the text does have, and on the way OUT of one it does not.
 *
 * The hook's `isLoading` flag cannot stand in for the comparison. It is raised by an effect keyed
 * on the data provider and selector (`create-use-data-hook.util.ts`), and effects run after the
 * commit, so the render that first pairs a new selector with the previous result still sees
 * `isLoading` false. Comparing identities has no such edge and needs no bookkeeping.
 *
 * Project ids are compared case-insensitively. C# canonicalizes them to uppercase and reports that
 * form in the exception, while a panel's own id arrives verbatim from a resource reference; the PDP
 * lookup folds case, so a casing mismatch is invisible on the data path and would surface only
 * here.
 *
 * @param options.resourceProjectId The project id the panel is reading from, or `undefined` if a
 *   resource has not resolved to one yet.
 * @param options.usjPossiblyError The chapter USJ, a `PlatformError`, or `undefined` if none yet.
 *   Whether `undefined` can reach here at all is the caller's choice of seed for its data hook. A
 *   caller seeding `undefined` (e.g., the Bible texts panel) says "nothing has arrived" through
 *   this value directly. One seeding a blank USJ (e.g.,
 *   `scripture-text-grid/resource-cell.component.tsx`) never can, because a blank USJ is neither
 *   `undefined` nor falsy, and must distinguish not-yet-arrived some other way — there,
 *   `resourceProjectId` not having resolved yet, plus the `isLoading` its own `deriveCellState`
 *   takes.
 * @param options.currentBookNum The book number the panel is currently displaying. A value of 0 or
 *   less means the panel has no book it can name, so no claim is made about one.
 * @param options.isUsjSettled Whether the chapter subscription has stopped loading. Answers "is the
 *   value in hand the CURRENT read's?", which both terminal branches need, because the data layer
 *   holds the last delivered value across a resubscription — it resets `isLoading`, never `data`.
 *
 *   Escalating out of `'loading'`: distinguishes an `undefined` that has not arrived yet from one
 *   that IS the answer — the data type's `getData` is `Usj | undefined` and the extender PDP
 *   returns `undefined` for a falsy USX, so a delivered `undefined` is reachable and would
 *   otherwise spin forever. This reports that case as `'failed'`, which is the honest answer for
 *   the only reference it can reach here — chapter 0, the book's front matter. For a real chapter
 *   the resource panel decides first that a delivered nothing is an EMPTY chapter and renders that
 *   message instead; see its `isBlankChapter`. A retry cannot change a deterministic `undefined`,
 *   so that precedence is what keeps an inert control off the state.
 *
 *   Entering `'loading'`: an error with a read in flight is the previous attempt's, so it is withheld
 *   rather than named. Without this, re-driving a failed read leaves the identical message on
 *   screen for the whole round trip and the retry affordance reads as inert.
 *
 *   The flag is re-armed from an effect, so for one render after a selector change it still reads
 *   settled. With USJ or `undefined` in hand that is invisible (the value is the previous
 *   reference's USJ, not `undefined`); with a stale error in hand it shows the old failure for a
 *   single render before the spinner replaces it.
 * @returns Which of the four content states to render.
 */
export function resolveResourceContentState({
  resourceProjectId,
  usjPossiblyError,
  currentBookNum,
  isUsjSettled,
}: {
  resourceProjectId: string | undefined;
  usjPossiblyError: unknown;
  currentBookNum: number;
  isUsjSettled: boolean;
}): ResourceContentState {
  if (!resourceProjectId) return 'loading';
  // Nothing in hand. Still on its way until the subscription says otherwise; once it has settled,
  // `undefined` is the delivered answer and there is no text to show.
  if (usjPossiblyError === undefined) return isUsjSettled ? 'failed' : 'loading';
  if (!isPlatformError(usjPossiblyError)) return 'ready';

  // Parsed once and compared, rather than calling `isMissingBookOnScreen` and then
  // `isMissingBookError`: one decision should not match the same message against both regexes twice.
  const missingBook = parseMissingBookError(usjPossiblyError);
  if (isMissingBookInfoOnScreen({ missingBook, currentBookNum, projectId: resourceProjectId }))
    return 'bookNotAvailable';

  // A missing-book failure naming some other book or resource is the previous selector's result,
  // held while the new subscription's first update is in flight — a spinner, not a fault. This is
  // the same ordering `deriveCellState` uses for the Scripture Text Grid, so the two surfaces cannot
  // give opposite answers about one error.
  if (missingBook || isMissingBookError(usjPossiblyError)) return 'loading';

  // An error with a read already in flight belongs to the PREVIOUS attempt. The data layer holds
  // the last delivered value across a resubscription — it resets `isLoading`, never `data` — so the
  // error survives both a retry and a plain navigation, and reporting it would name a failure for a
  // reference whose read has not finished. This is also what makes the retry affordance legible:
  // without it, re-driving the read leaves the identical message on screen for the whole round
  // trip, so pressing the button looks like it did nothing.
  if (!isUsjSettled) return 'loading';

  // Any other failure is terminal: the value in hand is an error rather than USJ, and nothing
  // re-emits until the data provider does. Naming it beats both a spinner that never resolves and an
  // editor with no scripture in it.
  return 'failed';
}

// #endregion Missing Book Detection

/** Localize key for the Text Collection tab's title and tooltip. */
export const SCRIPTURE_TEXT_GRID_TITLE_KEY = '%webView_scriptureTextGrid_title_multiple%';

/**
 * Builds the Text Collection's web view definition.
 *
 * Lives here rather than inline in the provider so the project-binding seam is reachable by a test:
 * `main.ts` is the extension entry point and no test imports it, so inline the precedence between
 * `openWebViewOptions.projectId` and `savedWebView.projectId` could be inverted — leaving the panel
 * on the outgoing project — with the whole suite still green.
 *
 * The web view's content and styles are passed in rather than imported: they are webpack `?inline`
 * assets, and importing them here would pull them into every consumer of this module.
 *
 * @param papi The instance of papi to read the interface mode and localized strings from.
 * @param savedWebView The saved definition being re-provided.
 * @param openWebViewOptions Options the caller passed to `openWebView`/`reloadWebView`.
 * @param webViewContent The web view's inline content and styles.
 * @returns The definition to provide.
 */
export async function buildScriptureTextGridWebView(
  papi: typeof PapiBackend,
  savedWebView: SavedWebViewDefinition,
  openWebViewOptions: TextCollectionPanelOptions,
  webViewContent: { content: string; styles: string },
): Promise<WebViewDefinition> {
  if (savedWebView.webViewType !== SCRIPTURE_TEXT_GRID_WEBVIEW_TYPE)
    throw new Error(
      `${SCRIPTURE_TEXT_GRID_WEBVIEW_TYPE} provider received request to provide a ${savedWebView.webViewType} web view`,
    );

  const projectId = resolveGridProviderProjectId(openWebViewOptions, savedWebView);
  const interfaceMode = await papi.settings.get('platform.interfaceMode');
  const titleLocalizedStrings = await papi.localization.getLocalizedStrings({
    localizeKeys: [SCRIPTURE_TEXT_GRID_TITLE_KEY],
  });

  return {
    ...savedWebView,
    title: SCRIPTURE_TEXT_GRID_TITLE_KEY,
    tooltip: titleLocalizedStrings[SCRIPTURE_TEXT_GRID_TITLE_KEY],
    isClosable: interfaceMode === 'power',
    shouldShowToolbar: false,
    projectId,
    content: webViewContent.content,
    styles: webViewContent.styles,
    // Drawn in the tab's text colour so it follows the theme, in both modes
    iconName: 'library',
    scrollGroupScrRef: interfaceMode === 'simple' ? 0 : savedWebView.scrollGroupScrRef,
  };
}
